    global _CT, _EH, _ESP, _LK, _camp_hits, allies_dpr, allies_rows, can_finish, card_num, carrier_target, ctype_of, enemy_track
    global escape_goal, espawn_d, fin_dmg, hold_target, home_altar_pos, hunt_busy, hunt_gate, hunt_keep, hunt_value, join_target, lead_tile, live_kit
