# ---- 69_ward.py (lazy: runs when 90_main calls _lazy_69_ward) ----
def _lazy_69_ward():
    global CAMP_OUT, GUARD_OUT, WARD_AT, WARD_BAD, WARD_CARRY, WARD_COST, WARD_EVERY, WARD_JUMP, WARD_POLL, WARD_REACH, WARD_SLACK, _WS
    global _altar_of, _toward, _ward_goal, _ward_ok, _ward_setup, _ward_tiles, enemy_wards, enemy_wards_seen, ward_turn
    # tzu: lazy
    """L4 Ward (ROLES_AND_LAYERS.md §1.2 ward_duty, §3 L4 Ward; INVARIANTS.md §3 step 6 housekeeping). P6, P7.

    Interface (called by 90_main's housekeeping, living champions only):
        ward_turn(w, s, task) -> 'ward' | None    place or relocate my free ward per my card's ward_duty
        enemy_wards(s) -> [Vec2]                  enemy wards visible this turn (memo per round), for 65/66/68
        enemy_wards_seen(since) -> {(x, y): rnd}  enemy wards seen at or after round `since` (they are permanent
                                                  until their owner moves them [rules])

    Mechanics: one free, permanent ward per champion, vision 6, placed within 2 tiles, a new one replaces the
    old [rules]; ward_cooldown() is 1 round after a placement [measured 14 Oct, runs/_ward/probe]; placing on a
    tile that holds an allied ward (my own included) raises "An allied ward already occupies this tile"
    [measured, same probe]; place_ward returns False for a newly revealed obstruction, other invalid tiles
    raise [sdk docstring]. The ward's vision is my own vision only (not shared) [rules], so it feeds this
    champion's vision.champions(), i.e. Flee, risk detours and the hunt layer.

    Duty target P (a tile we want watched), from the card (ward_duty: 0 Farmer/Hunter, 1 Guard, 2 Flex):
        carrier (task Bank, or bag >= bank_at_threat): P = the altar it banks at; the ward goes on the tile of
            my 2-tile square nearest to it, i.e. the next tile of the bank route (re-warded every WARD_EVERY)
        0 farm: P = the group my task walks to / clears, CAMP_OUT tiles from it toward the enemy spawn (its
            enemy-side approach: we see who arrives, and while clearing the approach is watched)
        1 guard: P = the home altar's approach, GUARD_OUT tiles from it toward the enemy spawn
        2 mid: P = the card's ward_target group (contested mid group nearest the enemy), CAMP_OUT toward them
    A duty ward is placed only when I can reach within WARD_AT of P (wards go within 2 tiles of me); until
    then the old ward stays where it is. With no ward at all, any target (else the enemy direction) is used at
    once, so a ward is up from the first turns. Relocation at most every WARD_EVERY rounds unless P moved
    more than WARD_JUMP since the last placement. Dead or channelling: nothing.
    Trace: ward|place x,y duty=<carry|farm|guard|mid|any> d=<tiles to P> (placements only);
           ward|enemy x,y (the first time an enemy ward tile is seen; only when someone calls enemy_wards).
    Fuel [measured 14 Oct, 9 maps x 2 sides vs starter, runs/_ward]: 14-22k per turn on average (polled every
    WARD_POLL rounds), 75-95k on an evaluation that places nothing, 110-190k on a placement turn; place_ward
    itself 5-9k, enemy_wards() 7-18k. Placement is skipped on turns below RESERVE + WARD_COST + WARD_SLACK.
    """

    if not cambc.is_draft():
        WARD_REACH = 2          # placed within 2 tiles [rules]; sdk constants.WARD_PLACEMENT_RADIUS
        WARD_EVERY = 8          # rounds between relocations of the same duty [provisional]
        WARD_JUMP = 6           # a duty target moved farther than this: relocate at once [provisional]
        WARD_AT = 3             # a ward within this of P counts as doing its duty [provisional]
        GUARD_OUT = 5           # Guard: the tile 4-6 from the home altar toward the enemy spawn [ROLES §1.2]
        CAMP_OUT = 2            # Farmer/Flex: the group's approach this far toward the enemy side [provisional]
        WARD_CARRY = True       # carriers re-ward toward their altar (off: a carrier keeps its farm/duty ward)
        WARD_POLL = 3           # rounds between evaluations while the task object is unchanged (fuel)
        WARD_COST = [20_000]    # worst place_ward cost seen, raised on every call [measured 14 Oct: 4.9k median, 9k max]
        WARD_SLACK = 100_000    # fuel kept after a placement for the rest of the turn [provisional]
        WARD_BAD = 30           # rounds a tile that refused a ward is skipped (an ally ward may move away)
        _WS = {"pos": None, "r": -99, "P": None, "bad": {}, "E": None, "blk": None, "ew_r": -1, "ew": [],
               "seen": {}, "dead": False, "next": 0, "task": None}

        def _ward_setup(w):
            """Once: the enemy spawn tile (World's anchor, else the mirror of my start) and the unplaceable mask
            (World's blocked mask: walls, holes, altars, camp spawn tiles, enemy spawn; else walls only)."""
            e = w.anchor.get("espawn")
            _WS["E"] = e if e is not None else V(w.W - 1 - w.last_pos.x, w.H - 1 - w.last_pos.y)
            _WS["blk"] = w.blocked if w.blocked is not None else game_map.walls()

        def _toward(w, a, n):
            """a moved n tiles (Chebyshev) toward the enemy spawn centre, clamped to the map."""
            e = _WS["E"]
            dx, dy = e.x - a.x, e.y - a.y
            m = max(abs(dx), abs(dy))
            if m == 0:
                return a
            if m < n:
                n = m
            x = a.x + int(round(dx * n / m))
            y = a.y + int(round(dy * n / m))
            return V(min(max(x, 0), w.W - 1), min(max(y, 0), w.H - 1))

        def _altar_of(w, s, key):
            ps = w.altar_pos
            if not ps:
                return None
            if isinstance(key, str) and key[:1] == "a" and key[1:].isdigit():
                i = int(key[1:])
                if i < len(ps):
                    return ps[i]
            p = s.pos
            return min(ps, key=p.chebyshev_distance)

        def _ward_goal(w, s, task):
            """(P, duty name) or (None, None)."""
            c = _S.get("card")
            if not c:
                c = None
            duty = getattr(c, "ward_duty", 0) if c is not None else 0
            key = None
            name = ""
            if task is not None and getattr(task, "status", "run") == "run":
                key = getattr(task, "key", None)
                name = type(task).__name__
            thr = getattr(c, "bank_at_threat", 20) if c is not None else 20
            if WARD_CARRY and (name == "Bank" or (s.bag > 0 and s.bag >= thr)):
                a = _altar_of(w, s, key if name == "Bank" else getattr(c, "home_altar", 255))
                return (a, "carry") if a is not None else (None, None)
            if duty == 1:
                i = getattr(c, "home_altar", 255)
                ps = w.altar_pos
                a = ps[i] if isinstance(i, int) and i < len(ps) else _altar_of(w, s, None)
                return (_toward(w, a, GUARD_OUT), "guard") if a is not None else (None, None)
            if duty == 2:
                h = getattr(c, "ward_target", 255)
                a = w.anchor.get(h) if h != 255 else None
                if a is not None:
                    return _toward(w, a, CAMP_OUT), "mid"
            if isinstance(key, int) and not isinstance(key, bool):
                a = w.anchor.get(key)
                if a is not None:
                    return _toward(w, a, CAMP_OUT), "farm"
            return None, None

        def _ward_ok(t, rnd):
            own = _WS["pos"]
            return not (_WS["blk"].is_set(t) or (own is not None and own == t) or _WS["bad"].get((t.x, t.y), -999) > rnd)

        def _ward_tiles(w, pos, P, rnd):
            """Placeable tiles of my 2-square nearest to P (at most 3). The Chebyshev-nearest tile alone first
            (one Vec2, one mask test, ~15k); else the square minus the blocked mask, intersected with growing
            squares around P (bitboard ops only: a positions() list + sort costs ~100-200k [measured])."""
            x = pos.x + max(-WARD_REACH, min(WARD_REACH, P.x - pos.x))
            y = pos.y + max(-WARD_REACH, min(WARD_REACH, P.y - pos.y))
            t = V(x, y)
            if _ward_ok(t, rnd):
                return [t]
            c = Bitboard()
            c.draw_chebyshev(pos, WARD_REACH)
            c &= ~_WS["blk"]
            own = _WS["pos"]
            if own is not None:
                c.set(own, False)
            k = t.chebyshev_distance(P)
            for _ in range(3):
                m = Bitboard()
                m.draw_chebyshev(P, k)
                m &= c
                if not m.is_empty():
                    return [q for q in m.positions()[:4] if _WS["bad"].get((q.x, q.y), -999) <= rnd][:3]
                k += 1
            return []

        def ward_turn(w, s, task=None):
            """Housekeeping (skeleton step 6), living champions. Returns 'ward' when a ward was placed.
            Evaluated every WARD_POLL rounds, or at once when the task object changed."""
            W = _WS
            if not s.alive:
                W["dead"] = True
                return None
            rnd = s.rnd
            if rnd < W["next"] and task is W["task"]:
                return None
            W["task"] = task
            W["next"] = rnd + WARD_POLL
            if s.st & (ST_RECALLING | ST_SUBMITTING | ST_TELEPORTING):
                return None
            if W["E"] is None:
                _ward_setup(w)
            elif W["blk"] is not w.blocked and w.blocked is not None:
                W["blk"] = w.blocked                              # World's mask arrived after the setup
            if W["dead"]:                                         # does a ward outlive its owner's death? re-read
                W["dead"] = False
                ps = w.me.ward_positions()
                W["pos"] = ps[0] if ps else None
            P, duty = _ward_goal(w, s, task)
            wp = W["pos"]
            dw = FAR
            if wp is not None:
                if P is None:
                    return None
                dw = wp.chebyshev_distance(P)
                if dw <= WARD_AT:
                    return None
                lp = W["P"]
                if rnd - W["r"] < WARD_EVERY and not (lp is None or lp.chebyshev_distance(P) > WARD_JUMP):
                    W["next"] = W["r"] + WARD_EVERY
                    return None
                if duty != "carry" and s.pos.chebyshev_distance(P) > WARD_REACH + WARD_AT:
                    return None                                   # not at the duty yet: the old ward stays
                if s.pos.chebyshev_distance(P) - WARD_REACH >= dw:
                    return None                                   # nothing in reach beats the ward we have
            elif P is None:
                P, duty = _toward(w, s.pos, WARD_REACH + 3), "any"
            if fuel() - RESERVE < WARD_COST[0] + WARD_SLACK:
                W["next"] = rnd + 1                               # place_ward is not cheap: wait for a lighter turn
                return None
            me = w.me
            if me.ward_cooldown() > 0:
                W["next"] = rnd + 1
                return None
            for t in _ward_tiles(w, s.pos, P, rnd):
                d = t.chebyshev_distance(P)
                if d >= dw:
                    return None                                   # no better than the ward we have
                f0 = fuel()
                try:
                    ok = me.place_ward(t)
                except Exception:
                    ok = False
                fc = f0 - fuel()
                if fc > WARD_COST[0]:
                    WARD_COST[0] = fc
                if not ok:
                    W["bad"][(t.x, t.y)] = rnd + WARD_BAD
                    W["next"] = rnd + 1
                    continue
                W["pos"], W["r"], W["P"] = t, rnd, P
                _ev("ward", f"place {t.x},{t.y} duty={duty} d={d} fuel={fc}")
                return "ward"
            return None

        def enemy_wards(s=None):
            """Enemy wards visible this turn (vision.wards returns visible wards only [sdk]); memo per round.
            Each new tile is remembered (enemy_wards_seen) and logged once (ward|enemy)."""
            W = _WS
            r = s.rnd if s is not None else cambc.round_number()
            if W["ew_r"] != r:
                W["ew_r"] = r
                ps = [x.position() for x in vision.wards(Team.ENEMY)]
                W["ew"] = ps
                seen = W["seen"]
                for p in ps:
                    k = (p.x, p.y)
                    if k not in seen:
                        _ev("ward", f"enemy {p.x},{p.y}")
                    seen[k] = r
            return W["ew"]

        def enemy_wards_seen(since=0):
            """{(x, y): last round seen} of enemy wards seen at or after `since`."""
            return {k: r for k, r in _WS["seen"].items() if r >= since}


_LAZY.append(('69_ward', 215, _lazy_69_ward))

# ---- 70_decide.py (lazy: runs when 90_main calls _lazy_70_decide) ----
def _lazy_70_decide():
    global ALTAR_MEM, ALTAR_SIGHT, AWAKE_HOLD, BANKHOME_REST, BANK_AVOID, BANK_BAD_N, BANK_SKIP, BANK_SLACK, CAMP_ROWS, CAP_FIXED, CAP_WHY, COOL
    global DEC_FUEL, DENY_R_GUARD, DENY_R_OTHER, Decider, ENDGAME, GROUP_SIGHT, HOME_NEAR, INT_ON, JOIN_R, LOW_HP_PICK, PRED_EST, REACH_MAX
    global RECHECK, REPICK_FUEL, RESP_WAIT, RISK_R, RISK_RECENT, Reach, Retreat, SCORE_FUEL, SEEN_CALM, SIGHT_DISCOUNT, SIGHT_R, SIGHT_RECENT
    global STATIC_FUEL, STATION_EARLY, STATION_ROUNDS, Station, StepOff, THREAT_RECENT, TICK_FUEL, WaitRespawn, w_d
    # tzu: lazy
    """L5: the interrupt order of INVARIANTS.md §2 as ONE table evaluated once per turn before acting, and the
    idle task choice of ROLES_AND_LAYERS.md §3 L5 (gems per round). Roles and claims come from L6 (80_team: w.team).

    Decider (the interface 90_main uses):
        tick(s) -> act       interrupts -> continue or switch -> task.step; sets key (tgt=), fight, hit
        shop(s) -> tok|None  housekeeping I7 (on spawn / dead)
        task_name(), death_cause(), died(s), work() (background: exact clear and pair predictions)
    Hooks wired here: 65_hunt (rows 4-6: Hold, Hunt, Join), 66_deny (row 5b, row 8 ClearLock, deny_watch), 67_group
    (pair_choice first in choose, pair_filter on the interrupt result, pair_after_end, pair_has_work, pair_work),
    80_team (w.team: my_role / my_card, claimed_groups, capturing_groups, sighting).
    Every goal change is explained by a `task|` end/start line or an `int|<EVENT>` line in the same round (I15).
    Rows that pause the current task (it resumes with its state): HUNT, JOIN, DENY, AWAKE, CAPTURE (passed-by),
    STEPOFF. Every other row ends it (task|<Name> abort why=<event>). FLEE (2) and EVADE (3) start a Retreat (trace
    name Flee) which is a veto: no lower row pre-empts it; it ends after FLEE_OK calm rounds out of reach.
    Commitment (ROLES L5): a group whose task failed rests (COOL), an altar whose Bank failed or was pre-empted
    rests BANK_SKIP rounds, so a task end never re-picks the same target at once.
    Play-only: the whole part sits under `if not cambc.is_draft()` (the draft never pays for these definitions).
    """

    if not cambc.is_draft():
        # Toggles per interrupt row (CLAUDE.md rule 1: every principle can be switched off and measured).
        # HUNT, JOIN and HOLD (fights against champions) start off: a Hunt costs farming time against the shard-buying
        # starter and has not beaten it yet. DENY (stun / lock on a channelling enemy) is on. Group takes: PAIR_ON (67).
        INT_ON = dict(FLEE=True, HUNT=False, DENY=True, JOIN=False, HOLD=False, HOME=True, AWAKE=True, CAPTURE=True,
                      BANK=True, STEPOFF=True)
        ENDGAME = 2000                  # last round [rules]
        BANK_SLACK = 5                  # endgame bank: rounds left < walk + ticks + this [INVARIANTS §2 event 10]
        SIGHT_R = 8                     # groups within this of a fresh sighting are discounted (P9) [provisional]
        SIGHT_RECENT = 10               # rounds a sighting counts for bank_at_threat / scoring [INVARIANTS I11]
        SIGHT_DISCOUNT = 0.5            # PROVISIONAL (no A# yet): value factor near a recent enemy sighting
        CAP_FIXED = 5                   # capture time added to every candidate's rounds [rules]
        JOIN_R = 6                      # ally under attack within this of us [INVARIANTS §2 event 6]
        HOME_NEAR = 10                  # bank at the home altar when it is at most this farther than the nearest
        COOL = dict(respawning=20, gate=30, lowhp=30, enemy=20, full=40, stuck=40, unseen=10, no_kit=60,
                    timeout=15, stall=100, ally_on=15, enemy_on=20, danger=10, broken=5, losing=30,
                    flee=20, evade=20, bank=0, home=0, capture=0, stepoff=0, awake=0,
                    no_partner=15, no_tank=10, contested=20, partner_left=30)   # rounds a failed group rests [provisional]
        # A group skipped for one of these reasons is logged cap|skip with the allowed why (I4) while it rests.
        CAP_WHY = dict(enemy="danger", flee="danger", evade="danger", danger="danger", losing="danger",
                       lowhp="lowhp", home="lowhp", ally_on="ally_on", enemy_on="enemy_on")
        BANK_SKIP = 15                  # PROVISIONAL (no A# yet): an altar whose Bank failed/aborted rests this long (L5:
                                        # a task that failed must not be re-picked at once)
        ALTAR_SIGHT = R1 + 2            # an altar within this of a recent enemy sighting is not a bank target (I13 at arrival)
        GROUP_SIGHT = R1 + 3            # a group within this of a recent sighting is not a ClearCamp candidate (P9)
        SEEN_CALM = 2                   # Flee: a sighting this recent still counts as "in reach" (bushes)
        BANKHOME_REST = 60              # PROVISIONAL (no A# yet): one bank-by-recall trip per this many rounds at most
                                        # (collision s2e: every 15 rounds cost more farming than it saved)
        THREAT_RECENT = 5               # a group/altar is avoided, and bank_at_threat applies, only for a sighting this
                                        # fresh of an enemy that beats us in the duel gate (P9 proportional: the starter
                                        # wanders everywhere)
        AWAKE_HOLD = 3                  # AWAKE row: calm rounds outside a woken group's range before resuming (it sleeps
                                        # after 2 rounds with nobody in range [measured A32]; resuming at once kept it awake)
        DENY_R_GUARD, DENY_R_OTHER = 6, 4   # row 5b search radius; non-Guards deny only what lands this turn
        DEC_FUEL = 700_000              # build the Decider only with this much above the reserve (setup turns)
        TICK_FUEL = 1_500_000           # first tick only with this much above the reserve (and not in the turn the
                                        # Decider was built); else the opening step. The first tick scores every group
                                        # (quick_clear each) and opens the first leg: 1.64M measured on monolith (13 Oct)
        SCORE_FUEL = 250_000            # scoring stops below this above the reserve (nearest groups first)
        STATIC_FUEL = 150_000           # background static_of jobs only with this much above RESERVE + BG_MARGIN
        PRED_EST = 1_000_000            # first guess of one background prediction; self-corrects upward [kit simcost 0.4-2M]
        LOW_HP_PICK = 0.6               # PROVISIONAL (no A# yet): without an exact prediction, pick only above this HP
        REPICK_FUEL = 900_000           # a second pick in one turn only with this much above the reserve
        REACH_MAX = 3                   # Reach legs per ClearCamp before a stall ends it
        RECHECK = 5                     # WaitRespawn re-asks for real work this often
        STATION_ROUNDS = 10             # nothing to clear: hold at the home altar, re-check for work this often
        STATION_EARLY = 60              # before this round Station re-checks every 3 rounds (pair predictions arrive)
        RISK_R = 8                      # I11: tiles within vision 8 [rules] of a sighting are the carrier's risk mask
        RISK_RECENT = 10                # I11: sightings this young count (own or team)
        ALTAR_MEM = 40                  # PROVISIONAL (no A# yet): an altar where a stronger enemy was seen is avoided
                                        # this long (collision: the starter returns to the one altar every few rounds)
        BANK_BAD_N = 2                  # Bank ends by evade/flee/enemy at one altar this often -> rest it BANK_AVOID
        BANK_AVOID = 60                 # PROVISIONAL (no A# yet)
        RESP_WAIT = 5                   # a ClearCamp that finds its group respawning within this many rounds waits
        CAMP_ROWS = {0: (1350, 20), 1: (2400, 60), 2: (500, 0), 3: (500, 0), 4: (20000, 200)}   # hp, Str [rules]

        # ---------------------------------------------------------------- small tasks owned by L5
        class StepOff(Task):
            """Event 11 (I12): off a captured group's spawn tile onto a free non-camp tile, then resume."""
            name = "StepOff"

            def step(self, w, s):
                if not w.camp_tiles.is_set(s.pos):
                    return self.end(s, "ok", "off")
                if not s.can_move:
                    return "run"
                wl = walls(w, s) | w.camp_tiles
                for dv in DIRS:
                    q = s.pos + dv
                    if not wl.is_set(q) and w.nav.move(q):
                        self.act = "mv how=off"
                        return self.end(s, "ok", "off")
                return "run"

        class WaitRespawn(Task):
            """The soonest-respawning group is about due: walk there and wait (I8 allows respawn_wait r <= 5)."""
            name = "WaitRespawn"

            def __init__(self, h, until):
                Task.__init__(self, h)
                self.until = until

            def step(self, w, s):
                left = self.until - s.rnd
                if left <= 0:
                    return self.end(s, "ok", "due")
                dec = getattr(self, "dec", None)
                if dec is not None and (s.rnd - self.r0) % RECHECK == RECHECK - 1 and dec.real_work(s):
                    return self.end(s, "ok", "recheck")
                # nowork=1: chosen only when no clearable group, no bank and no shop/heal trip exists (I8 allows
                # any r then); re-checked every RECHECK rounds above.
                if w.dist(self.key, s.pos) == 0:                  # on the ring: no new leg per turn
                    self.act = f"wait why=respawn_wait g={self.key} r={left} nowork=1"
                    return "run"
                r = self.goto(w, self.key)
                if r in ("full", "stuck"):
                    return self.end(s, "fail", r)
                if r == "here":
                    self.act = f"wait why=respawn_wait g={self.key} r={left} nowork=1"
                return "run"

        class Reach(Task):
            """Walk to the melee ring of one camp (key "c<x>_<y>") that a paused ClearCamp cannot reach by its
            greedy step; ok on arrival, then the clear resumes."""
            name = "Reach"

            def step(self, w, s):
                r = self.goto(w, self.key)
                if r == "here":
                    return self.end(s, "ok", "here")
                if r in ("full", "stuck"):
                    return self.end(s, "fail", r)
                return "run"

        class Retreat(Flee):
            """Events 2/3 and the awake-camp step-out (I2, I3, I10) with hysteresis. The trace name stays Flee.
            In the danger mask: 60_tasks' flee_step (lowest steps-to-safety). Outside it: never step back in; step
            away from every visible or just-seen enemy (spawn only as the tie-break, so a retreat never walks to
            spawn THROUGH the enemy). Ends ok after `need` consecutive rounds outside the mask with no enemy within
            R1 + 1 (enemy threat: FLEE_OK = 3; camp threat: 1, the camp never chases)."""

            def __init__(self, threat="camp", need=FLEE_OK):
                Flee.__init__(self, threat)
                self.need = need

            def step(self, w, s):
                holds, inc, t, k = flee_cond(w, s)
                if holds:
                    _ev("flee", f"hp={int(s.hp)} inc={inc} ttd={t} sts={k} bag={s.bag} why={self.threat}")
                d = danger(w, s)
                foes = [e[0] for e in s.enemies]
                fresh = foes + [q for r, q in _S["seen"] if r >= s.rnd - SEEN_CALM]
                near = min((q.chebyshev_distance(s.pos) for q in fresh), default=FAR)
                inside = d.is_set(s.pos)
                if inside or holds or near <= R1 + 1:
                    self.calm = 0
                else:
                    self.calm += 1
                    if self.calm >= self.need:
                        return self.end(s, "ok", "safe")
                if not s.can_move:
                    self.act = "wait why=blocked"
                    return "run"
                if inside and flee_step(w, s):
                    self.act = "mv how=fl"
                    return "run"
                if not inside and self.threat == "camp" and not fresh:
                    self.act = "wait why=hold"                     # a camp never chases: wait for it to sleep here
                    return "run"
                if self.away(w, s, d, foes + [q for r, q in _S["seen"]]):
                    self.act = "mv how=fl"
                    return "run"
                self.act = "wait why=blocked" if inside else "wait why=hold"   # out of reach already: hold, not stuck
                return "run"

            def away(self, w, s, d, foes):
                """One step outside the danger mask that gains distance on the nearest foe, or keeps it and gets
                nearer spawn (without foes: only nearer spawn). Never a step towards a foe."""
                wl = walls(w, s)
                pos = s.pos
                cap = R1 + 4
                e0 = min(min((q.chebyshev_distance(pos) for q in foes), default=FAR), cap)
                s0 = w.dist("spawn", pos)
                s0 = FAR if s0 is None else s0
                best = None
                for dv in DIRS:
                    q = pos + dv
                    try:
                        if wl.is_set(q) or d.is_set(q):
                            continue
                    except Exception:
                        continue
                    e = min(min((f.chebyshev_distance(q) for f in foes), default=FAR), cap)
                    sd = w.dist("spawn", q)
                    sd = FAR if sd is None else sd
                    if not (e > e0 or (e == e0 and sd < s0)):     # never closer to a foe; no sideways shuffle
                        continue
                    sc = (e, -sd)
                    if best is None or sc > best[0]:
                        best = (sc, q)
                return best is not None and w.nav.move(best[1])

        class Station(Task):
            """Nothing clearable (no solo group, all resting): hold the home altar's ring (P3: guard the bank;
            the Guard's ground). Every STATION_ROUNDS it asks the decider whether there is work; it ends only
            then (no task churn on maps with nothing to do)."""
            name = "Station"

            def step(self, w, s):
                dec = getattr(self, "dec", None)
                every = STATION_ROUNDS if s.rnd > STATION_EARLY else 3    # the opening: predictions land within rounds
                if (s.rnd - self.r0) % every == every - 1 and (dec is None or dec.has_work(s)):
                    return self.end(s, "ok", "recheck")
                if getattr(self, "parked", False) or w.dist(self.key, s.pos) == 0:
                    self.act = "wait why=hold"                     # no new Nav leg per waiting turn
                    return "run"
                if self.goto(w, self.key) in ("full", "stuck", "here"):
                    self.parked = True
                    self.act = "wait why=hold"
                return "run"

        def w_d(w, h, s):
            d = w.dist(h, s.pos)
            return s.pos.chebyshev_distance(w.anchor[h]) if d is None else d

        # ---------------------------------------------------------------- the decider
        class Decider:
            def __init__(self, w, nav):
                w.nav = nav
                self.w, self.nav = w, nav
                self.kit = my_kit(w)                          # the tasks' Kit (60_tasks), also L3's KIT global
                globals()["KIT"] = self.kit
                plan = self.plan = w.plan if w.plan_ok else None
                self.slot = plan.slot_of(w.ctype) if plan is not None else None
                self.base = plan.card_for(w.ctype) if plan is not None else None
                self.size = plan.team_size if plan is not None else 0
                self.cards = [plan.cards[i] for i in range(self.size)] if plan is not None else []
                self.route = list(self.base.route) if self.base is not None else []
                self.task = self.paused = None
                self.key = self.fight = self.hit = None
                self.role = None
                self.cool = {}              # group -> round it may be picked again
                self.static = {}            # group -> (value, rounds, dmg): A41 value, quick_clear (pessimistic)
                self.pred = {}              # group -> (rounds, dmg, casts) exact, from full HP (background)
                self.pq = list(w.order)     # background prediction queue, nearest first
                self.sq = list(w.order)     # background static_of queue, nearest first
                self.dead_r = {}            # group -> round its passed-by dead check ran
                self.ally_hp = {}           # ally id -> HP last seen (event 6)
                self.fired = {}             # event -> count (the `ints` line at death / game end)
                self.ally_cap = set()       # groups an alive ally is capturing this round (claims)
                self.skip_r = {}            # group -> last round a cap|skip ally_on was logged
                self.pcost = PRED_EST
                self.ticked = False
                self.built = -1             # round the Decider was built (90_main: no tick in that turn)
                self.blk = 0                # consecutive turns the task ended with wait why=blocked
                self.reached = {}           # ClearCamp task id -> Reach legs it had
                self.skip = {}              # (task name, str key) -> round it may be picked again (BANK_SKIP)
                self.cool_why = {}          # group -> reason of its rest (cap|skip why, I4)
                self.hp_prev = None         # HP at the end of the last tick (event 3: hit by an enemy)
                self.threats = []           # (round, pos) of enemies the duel gate says we lose to (P9 avoidance)
                self.home_r = -999          # round a GoHome last ended ok (BANKHOME rests BANK_SKIP after it)
                self.deny_now = False       # row 5b's deny lands this turn (inline when a task is paused already)
                self.elig = {}              # card side mask -> eligible groups (candidates' static filter)
                self.tseen = []             # (stamp round, (x, y), err) team sightings, RISK_RECENT rounds (I11)
                self.altar_bad = {}         # altar index -> last round a stronger enemy was seen within ALTAR_SIGHT
                self.bank_bad = {}          # altar key -> Bank ends by evade/flee/enemy since its last bank
                w.risk = None
                self.card = None
                self.set_role(self.base.role if self.base is not None else ROLE_FARMER)

            # ------------------------------------------------------------ roles (L6)
            def set_role(self, role, card=None):
                """Role and card: the card 80_team computed (w.team.my_card), else my planned card, else the role's
                defaults (TeamCard over my planned card)."""
                if role == self.role and (card is None or card is self.card):
                    return
                old, self.role = self.role, role
                b = self.base
                c = card if card is not None else (b if b is not None and b.role == role else TeamCard(role, b))
                _S["card"] = c                                    # 60_tasks reads every card field through card()
                self.card = c
                try:
                    self.w.me.set_priority(int(c.priority))       # once at start and on a role change (ROLES §1.2)
                except Exception:
                    pass
                if old is not None:
                    trace("role", f"{old}->{role} priority={c.priority}")

            def team(self):
                t = getattr(self.w, "team", None)
                return t if t is not None and t.ready else None

            def update_role(self, s):
                """L6 (80_team): the role of my slot from the alive mask; keeps the task (A42)."""
                t = self.team()
                if t is None or t.my_card is None or self.slot is None:
                    return
                self.set_role(t.my_role, t.my_card)

            def watch_claims(self, s):
                """Allies capturing g (Variant A: claim + capturing bit): g respawns after its timer, so it rests that
                long. Every group an alive ally claims counts as ally_on for event 9 (I5): never join its capture."""
                t = self.team()
                self.ally_cap = set()
                if t is None:
                    return
                self.ally_cap = set(t.claimed_groups)
                if t.variant != "A":
                    return                                         # B stores no capturing bit: no respawn rest
                for code in t.capturing_groups:
                    if code is not None and code >= 0 and code in self.w.groups:
                        try:
                            u = s.rnd + CAP_FIXED + self.w.groups[code].max_respawn_timer()
                        except Exception:
                            u = s.rnd + 40
                        if self.cool.get(code, -1) < u:
                            self.cool[code] = u

            # ------------------------------------------------------------ helpers
            def c(self, k):
                return card(self.w, k)

            def watch_threats(self, s):
                """Log the visible enemies we would lose a duel to (I3's one model); only these steer avoidance."""
                th = self.threats
                for p, hp, bag, ch in s.enemies:
                    if not self.gate(s, ch, hp, bag):
                        th.append((s.rnd, p))
                while th and th[0][0] < s.rnd - SIGHT_RECENT:
                    th.pop(0)

            def update_risk(self, s):
                """I11: the carrier risk mask Nav reads (w.risk): tiles within RISK_R of an enemy the duel gate says
                beats us (self.threats, as bank_target's altar memory) seen in the last RISK_RECENT rounds, only while
                bag >= bank_at_threat. Also the per-altar threat memory. Team sightings (no champion type, so no
                gate) stay out of the mask; Bank.step and bank_target still act on them."""
                w = self.w
                w.risk = None
                w.risk_pts = ()
                t = self.team()
                sg = t.sighting if t is not None else None
                if sg is not None:
                    st, xy = s.rnd - sg[2], (sg[0], sg[1])
                    if not self.tseen or self.tseen[-1][0] != st or self.tseen[-1][1] != xy:
                        self.tseen.append((st, xy, t.sight_err))
                while self.tseen and self.tseen[0][0] < s.rnd - RISK_RECENT:
                    self.tseen.pop(0)
                th = self.threat_pos(s, 0)
                if th:
                    for i, a in enumerate(w.altar_pos):
                        if any(q.chebyshev_distance(a) <= ALTAR_SIGHT for q in th):
                            self.altar_bad[i] = s.rnd
                bat = self.c("bank_at_threat")
                if s.bag < bat:
                    return
                pts = {(q.x, q.y): RISK_R for q in self.threat_pos(s, RISK_RECENT)}
                if not pts:
                    return
                m = Bitboard()
                for (x, y), r in pts.items():
                    m.draw_chebyshev(V(x, y), r)
                w.risk, w.risk_pts, w.risk_bag, w.risk_bat = m, list(pts), s.bag, bat

            def threat_pos(self, s, recent):
                return [q for r, q in self.threats if r >= s.rnd - recent]

            def claimed(self):
                """Groups an alive ally claims (80_team: ClearCamp, Capture, GroupTake, WaitRespawn targets)."""
                t = self.team()
                return t.claimed_groups if t is not None else frozenset()

            def altar_key(self, s):
                """The home altar's key unless it is much farther than the nearest altar (I13 fallback: nearest)."""
                w = self.w
                i = self.c("home_altar") if w.plan_ok else 255
                if i is not None and i != 255:
                    dh, dn = w.dist(f"a{i}", s.pos), w.dist("altar", s.pos)
                    if dh is not None and dh < FAR and (dn is None or dh <= dn + HOME_NEAR):
                        return i
                return None

            # ------------------------------------------------------------ §2: the interrupt table
            def interrupts(self, s):
                """One pass, first match wins. Returns (EVENT, task, pauses, text) or None (continue / choose)."""
                w, t = self.w, self.task
                name = t.name if t is not None else None
                kit = self.kit
                # 1 channel running: the channelling task decides (GoHome cancels an unsafe recall, Bank sees a lock)
                if s.st & (ST_RECALLING | ST_SUBMITTING | ST_TELEPORTING):
                    return None
                # 2 about to die (P3: dangers before opportunities). ClearCamp runs its own step-out for a camp-only
                # threat; an enemy champion in reach is this row's business for every task.
                holds, inc, ttd_, k = flee_cond(w, s)
                near = any(e[0].chebyshev_distance(s.pos) <= R1 for e in s.enemies)
                if INT_ON["FLEE"] and holds and name != "Flee" and (name != "ClearCamp" or near):
                    th = "both" if near and s.awake else ("enemy" if near else "camp")
                    # A ClearCamp is paused, not ended: it resumes on the same group after the retreat (no COOL rest
                    # and no re-pick; its own gates re-check the enemy). Measured vs starter: 20-27 ClearCamp aborts
                    # by flee per game, 93-347 rounds, the group then taken by the starter.
                    return "FLEE", Retreat(th, FLEE_OK if near else 1), name == "ClearCamp", \
                        f"hp={int(s.hp)} inc={inc} ttd={ttd_} sts={k} bag={s.bag} why={th}"
                # Flee is a veto: once retreating, nothing below pre-empts it until it ends (hysteresis inside it).
                # This is what stops the Bank <-> Flee ping-pong (hundreds of 1-round tasks per game).
                if name == "Flee":
                    if INT_ON["CAPTURE"] and w.tile_group is not None:
                        self.passed_dead(s, None, "danger")        # I4: a dead group passed while fleeing is a skip
                    return None
                # 3 losing fight vs a champion (I3): hit this turn by an enemy in reach that the duel gate says we
                # can't beat, or carrying a bag with one at its walk + attack reach: leave (P8 avoid strength).
                if INT_ON["FLEE"] and near and self.hp_prev is not None:
                    hit = s.hp < self.hp_prev
                    for p, hp, bag, ch in s.enemies:
                        dd = p.chebyshev_distance(s.pos)
                        if dd <= R1 and (hit or (s.bag > 0 and dd <= 3)) and not self.gate(s, ch, hp, bag):
                            return "EVADE", Retreat("enemy"), False, \
                                f"vs=c{int(ch)} d={dd} hp={int(s.hp)} hit={int(hit)} bag={s.bag}"
                # 4 capture contested (65_hunt): an enemy within R1 of the region we capture. Capture's own step
                # skips (enemy_on) when it stands ON the region; here: hold the tile if the champion gate passes.
                if INT_ON["HOLD"] and name == "Capture" and s.enemies:
                    tile = s.pos if getattr(t, "on", None) is not None else w.anchor.get(t.key, s.pos)
                    r = hold_target(w, s, tile, kit)
                    if r is not None and r[1]:
                        return "HOLD", Hold(tile), True, r[2]
                # 5b enemy channel in stun / lock reach (66_deny): a stun or a fresh lock cancels it [rules] (P8, P14,
                # P15). Before row 5: a deny lands this turn, a hunt only after rounds. The Guard looks farther (6); the
                # others deny only what lands this turn (turns == 0).
                if INT_ON["DENY"] and s.enemies and name not in ("Deny", "Flee"):
                    g = self.role == ROLE_GUARD
                    cand = deny_candidate(w, s, DENY_R_GUARD if g else DENY_R_OTHER)
                    if cand is not None and (g or cand[2] == 0):
                        ch, how, tn = cand
                        if tn == 0 or self.paused is None or t is None:
                            self.deny_now = tn == 0
                            return "DENY", Deny(ch[0], ch[5]), True, \
                                f"vs=c{int(ch[0])} how={how} t={tn} kind={ch[2]} rem={ch[3]} bag={ch[4]}"
                # 5 enemy carrier in reach (65_hunt; intercept_radius 0 = never: Farmers), P8, P13. Rows 5 and 6 never
                # pre-empt GoHome (P3; measured s2d collision: HUNT <-> BANKHOME ping-pong, 49 Hunt + 42 GoHome aborts).
                if INT_ON["HUNT"] and s.enemies and name not in ("Hunt", "Hold", "Bank", "Deny", "Flee", "GoHome") \
                        and not (name == "Capture" and getattr(t, "on", None) is not None):
                    r = carrier_target(w, s, self.cur_vpr(s), kit)
                    if r is not None:
                        return "HUNT", Hunt(r[0]), True, r[1]
                # 6 ally under attack nearby: Join = Hunt on the enemy nearest the ally (P10, P19)
                if INT_ON["JOIN"] and s.enemies and name not in ("Hunt", "Hold", "Bank", "Deny", "Flee", "GoHome"):
                    me = int(w.me)
                    for a in vision.champions(Team.ALLY):
                        if int(a) == me:
                            continue
                        ap, ahp = a.position(), a.health()
                        was = self.ally_hp.get(int(a))
                        self.ally_hp[int(a)] = ahp
                        if was is None or ahp >= was or ap.chebyshev_distance(s.pos) > JOIN_R:
                            continue
                        r = join_target(w, s, ap, kit)
                        if r is not None:
                            return "JOIN", Hunt(r[0]), True, f"{r[1]} ally=c{int(a)}"
                # 7 low HP, not under fire: home (the recall itself only under I1, inside GoHome)
                if INT_ON["HOME"] and inc == 0 and s.hp < self.c("recall_hp") * s.max_hp \
                        and name != "GoHome" and not w.spawn.is_set(s.pos):
                    return "HOME", GoHome("heal"), False, f"hp={int(s.hp)}/{int(s.max_hp)}"
                # I10: standing in range of an awake group we are not fighting (woken by someone else): step out,
                # then resume (Nav routes around awake ranges). Not lethal, else row 2 would have fired.
                if INT_ON["AWAKE"] and inc > 0 and s.awake and name not in ("Capture", "StepOff"):
                    own = t.key if name == "ClearCamp" else None
                    if not (own is not None and getattr(t, "f", None) is not None):
                        for h in s.awake:
                            if h == own:
                                continue
                            for (sp, kd), hp in zip(kinds(w, h), s.camp_hp.get(h) or ()):
                                if hp and sp.chebyshev_distance(s.pos) <= (5 if kd == MONO else CAMP_RANGE):
                                    return "AWAKE", Retreat("camp", AWAKE_HOLD), True, f"g=g{h} inc={inc}"
                # 8 altar lock on the target altar: Bank ends fail why=locked (at arrival, or a lock broke its channel);
                # after_end runs ClearLock (I13) and Bank again once the lock is gone
                # 9 a cleared camp passed by (I4; P13: capturing theirs is worth double)
                cur = t if t is not None else self.paused
                if INT_ON["CAPTURE"] and name != "Capture" and w.tile_group is not None:
                    own = cur.key if cur is not None and cur.name == "ClearCamp" else None
                    engaged = own is not None and (getattr(cur, "f", None) is not None or
                                                   all(x is None for x in s.camp_hp.get(own, (1,))))
                    busy = "danger" if engaged else ("lowhp" if name == "GoHome" and t.reason == "heal" else None)
                    hold = self.passed_dead(s, own, busy)
                    if hold is not None:
                        return "CAPTURE", Capture(hold[0]), True, f"g=g{hold[0]} d={hold[1]}"
                # 10 bag over threshold (P3: bank before the bag becomes the enemy's prize). Not during a capture
                # (it pays in a few rounds) nor mid-clear, except the endgame; only to an altar not backed off.
                if INT_ON["BANK"] and s.bag > 0 and name not in ("Bank", "ClearLock", "GoHome"):
                    busy = (name == "ClearCamp" and getattr(t, "f", None) is not None) or name == "Capture"
                    left = ENDGAME - s.rnd
                    walk = w.dist("altar", s.pos)
                    walk = s.pos.chebyshev_distance(w.anchor.get("altar", s.pos)) if walk is None else walk
                    why = None
                    if walk < FAR and left < walk + max(1, -(-s.bag // 10)) + BANK_SLACK:
                        why = "endgame"
                    elif not busy and s.bag >= self.c("bank_at"):
                        why = "bag"
                    elif not busy and s.bag >= self.c("bank_at_threat") and self.threat_pos(s, THREAT_RECENT):
                        why = "threat"                             # a duel we lose was in sight lately (not any sighting)
                    if why is not None:
                        i = self.bank_target(s, why == "endgame")
                        if i is not None:
                            return "BANK", Bank(i), False, f"bag={s.bag} why={why} walk={walk} altar=a{i}"
                        # No altar qualifies (all backed off or contested): carry the bag home by recall instead of
                        # farming on with it (P3; the collision loop: Bank fail enemy -> EVADE -> ClearCamp with 66).
                        if why == "bag" and not w.spawn.is_set(s.pos) and s.rnd - self.home_r > BANKHOME_REST:
                            return "BANKHOME", GoHome("bank"), False, f"bag={s.bag} why={why} walk={walk}"
                # 11 standing on a captured group's spawn tile (I12)
                if INT_ON["STEPOFF"] and name not in ("Capture", "StepOff") and w.tile_group is not None \
                        and w.camp_tiles is not None and w.camp_tiles.is_set(s.pos):
                    h = w.tile_group.get(s.pos)
                    if h is not None and w.gstate(h) == "respawning":
                        return "STEPOFF", StepOff(h), True, f"g=g{h}"
                # 12 continue, unless the task has stood still: I8 allows 2 blocked rounds, so the third ends it
                # (e.g. a fight whose last camp is out of reach behind camp tiles)
                if t is not None and self.blk >= 2 and name not in ("Capture", "WaitRespawn", "Station"):
                    self.blk = 0
                    if name == "ClearCamp" and self.reached.get(id(t), 0) < REACH_MAX:
                        live = [c.spawn_position() for c, hp in zip(w.camps[t.key], s.camp_hp.get(t.key) or ()) if hp]
                        if live:                                   # the last camps sit behind the others: walk round
                            q = min(live, key=s.pos.chebyshev_distance)
                            self.reached[id(t)] = self.reached.get(id(t), 0) + 1
                            return "REACH", Reach(f"c{q.x}_{q.y}"), True, f"g=g{t.key} camp={q.x},{q.y}"
                    return "STALL", None, False, f"task={name} g={gid(t.key)}"
                return None                                        # 13 choose

            def passed_dead(self, s, own, busy):
                """Event 9 (I4, P13: theirs is worth double): the nearest dead group within NEAR_DEAD that we may
                take, as (h, d); groups we may not take get one cap|skip line per episode with an allowed why.
                busy = the why every group gets now (danger: fleeing or mid-clear; lowhp: going home to heal)."""
                w = self.w
                hold = None
                for tile, h in s.near_t:
                    if tile.chebyshev_distance(s.pos) > NEAR_DEAD or self.dead_r.get(h) == s.rnd or h == own:
                        continue
                    self.dead_r[h] = s.rnd
                    row = s.camp_hp.get(h)
                    if row is None or not all(x is None for x in row):
                        continue
                    ally = h in self.ally_cap or \
                        not (vision.champion_tiles(Team.ALLY) & spawn_tiles(w, h)).is_empty()     # I5: claimed = theirs
                    why = "ally_on" if ally else busy
                    if why is None and self.cool.get(h, -1) > s.rnd:
                        # resting after a danger/lowhp end: skip with that why. Resting for any other reason (our
                        # own capture's respawn timer, a stall) is stale now that it reads dead: take it.
                        why = CAP_WHY.get(self.cool_why.get(h))
                    if why is not None:                            # I4: one skip line per episode, allowed whys only
                        if self.skip_r.get(h, -9) >= s.rnd - 1:
                            self.skip_r[h] = s.rnd
                        elif w.gstate(h) == "dead":
                            ev("cap", f"skip g=g{h} why={why}")
                            self.skip_r[h] = s.rnd
                        continue
                    if hold is None and w.gstate(h) == "dead":
                        hold = (h, tile.chebyshev_distance(s.pos))
                return hold

            def bank_target(self, s, endgame=False):
                """Altar index for Bank: not backed off (BANK_SKIP after a failed/aborted Bank there), reachable,
                not within ALTAR_SIGHT of a fresh sighting of an enemy that beats us (it would fail `enemy`, I13; ignored
                in the endgame); the home altar unless it is HOME_NEAR farther than the best. None = no altar."""
                w = self.w
                # A carrier walks to the altar: any enemy seen there in the last THREAT_RECENT rounds, or one that
                # beats us seen in SIGHT_RECENT, makes it a no (measured: a Vendetta walked into one and died, s2c).
                seen = () if endgame else [q for r, q in _S["seen"] if r >= s.rnd - THREAT_RECENT] + \
                    self.threat_pos(s, SIGHT_RECENT)
                # the team's sighting too (review: Ryth's sighting at a0 was in shared memory when Varg died there)
                tsee = () if endgame else [(V(xy[0], xy[1]), e) for st, xy, e in self.tseen if st >= s.rnd - SIGHT_RECENT]
                risk = None if endgame else w.risk               # a carrier: no altar inside the I11 mask
                home = self.c("home_altar") if w.plan_ok else 255
                best = hd = None
                for i, a in enumerate(w.altar_pos):
                    k = f"a{i}"
                    if self.skip.get(("Bank", k), -1) > s.rnd:
                        continue
                    if any(q.chebyshev_distance(a) <= ALTAR_SIGHT for q in seen):
                        continue
                    if any(q.chebyshev_distance(a) <= ALTAR_SIGHT + e for q, e in tsee):
                        continue
                    if not endgame and self.altar_bad.get(i, -999) >= s.rnd - ALTAR_MEM:
                        continue
                    if risk is not None and risk.is_set(a):
                        continue
                    d = w.dist(k, s.pos)
                    if d is None:
                        d = s.pos.chebyshev_distance(a)
                    if d >= FAR:
                        continue
                    if i == home:
                        hd = d
                    if best is None or d < best[0]:
                        best = (d, i)
                if best is None:
                    return None
                if hd is not None and hd <= best[0] + HOME_NEAR:
                    return home
                return best[1]

            def resp_timer(self, h):
                try:
                    st = self.w.groups[h].state()
                    return int(st.timer) if isinstance(st, game_map.CampGroupRespawning) else None
                except Exception:
                    return None

            def has_work(self, s):
                """Station's re-check: a group take, a candidate group, a bag with an altar to bank at, or a respawn."""
                if pair_has_work(self, s):
                    return True
                if s.bag > 0 and self.bank_target(s) is not None:
                    return True
                if self.candidates(s):
                    return True
                claimed = self.claimed()
                return any(u > s.rnd and h not in claimed and self.solo_ok(h) for h, u in self.cool.items())

            def real_work(self, s):
                """WaitRespawn's re-check: a group take, a candidate group or a bag with an altar (not resting groups)."""
                if pair_has_work(self, s):
                    return True
                return bool((s.bag > 0 and self.bank_target(s) is not None) or self.candidates(s))

            def gate(self, s, ch, hp, bag):
                """The one duel model (I3): L3's duel_gate against this enemy's design kit."""
                try:
                    return duel_gate(self.kit, s, kit_of(int(ch.champion_name())), hp, their_bag=bag).ok
                except Exception:
                    return False

            def cur_vpr(self, s):
                """Gems per round the current task earns (row 5's bar for a hunt): a group's static value over its
                walk + clear + capture, else the alive income [measured A12]."""
                t = self.task
                if t is not None and isinstance(t.key, int) and t.key in self.w.groups:
                    v, r, _ = self.static_of(t.key)
                    d = self.w.dist(t.key, s.pos) or 0
                    if r < FAR:
                        return max(INCOME, v / (min(d, FAR) + r + CAP_FIXED))
                return INCOME

            # ------------------------------------------------------------ 13: the idle choice (gems per round)
            def static_of(self, h):
                """(value, rounds, dmg) of group h from the plan's columns (cheap) or the camps (no plan, ~35k)."""
                v = self.static.get(h)
                if v is not None:
                    return v
                w, plan = self.w, self.plan
                if plan is not None and h < len(plan.groups):
                    r = plan.groups[h]
                    if r.d_ours == 255:
                        v = (0, FAR, FAR)
                    else:
                        comp = [CAMP_ROWS[0]] * r.wolves + [CAMP_ROWS[1]] * r.elks + \
                               [CAMP_ROWS[2]] * (r.gem_cl + r.gold_cl) + [CAMP_ROWS[4]] * r.monoliths
                        q = quick_clear(self.kit, comp)
                        v = (r.gems + r.gold * GOLD_GEM, q[0], q[1])
                else:
                    g = w.groups[h]
                    q = quick_clear(self.kit, [(m[1], m[2], m[3], m[4]) for m in group_comp(w, h)])
                    v = (g.gem_value() + g.gold_value() * GOLD_GEM, q[0], q[1])
                self.static[h] = v
                return v

            def solo_ok(self, h):
                """My solo bit for h (plan), else the cached static estimate says a clear is finite."""
                plan, slot = self.plan, self.slot
                if plan is not None and slot is not None and h < len(plan.groups):
                    return bool(plan.groups.column(12)[h] >> slot & 1) or self.pred_ok(h)
                v = self.static.get(h)
                return v is not None and v[1] < FAR

            def pred_ok(self, h, hp=None, keep=None):
                """The exact background prediction (full HP, cooldowns ready) passes the solo gate: it overrides a
                missing solo bit (the draft's quick estimate is pessimistic)."""
                p = self.pred.get(h)
                if p is None or p[0] >= FAR:
                    return False
                mx = self.kit.max_hp if self.kit is not None else 0
                hp = mx if hp is None else hp
                keep = self.c("keep_hp") * mx if keep is None else keep
                return p[1] * SOLO_SAFETY < hp - keep

            def eligible(self, sides):
                """[(h, solo bit set for my slot)] of the groups on my card's sides, nearest-first (static)."""
                w, plan, slot = self.w, self.plan, self.slot
                if plan is None:
                    return [(h, True) for h in w.order]
                n = len(plan.groups)
                fl, solo = plan.groups.column(11), plan.groups.column(12)
                out = []
                for h in w.order:
                    if h < n:
                        if not sides >> (fl[h] & 3) & 1:
                            continue
                        out.append((h, slot is None or bool(solo[h] >> slot & 1)))
                    else:
                        out.append((h, True))
                return out

            def candidates(self, s):
                """[(score, h)] of solo ClearCamp targets per the card (sides, solo bits), claims, sightings.
                Score = (gems + gold x A41) / (walk + predicted clear + 5) [ROLES L5]; the exact prediction when
                the background has it, else quick_clear (pessimistic). Stops when fuel is short (I9: a full scan cost
                1.4M on lanes' 42 groups, ~200 fuel per bytecode); groups are visited nearest-first from the start."""
                w, plan, slot = self.w, self.plan, self.slot
                pos, rnd = s.pos, s.rnd
                claimed = self.claimed()
                sides = self.c("sides")
                keep = self.c("keep_hp") * s.max_hp
                fresh = self.threat_pos(s, THREAT_RECENT)       # skip: a losing duel stands there now
                seen = self.threat_pos(s, SIGHT_RECENT)         # discount: one was there lately (P9)
                el = self.elig.get(sides)
                if el is None:                                     # static filters once per card side mask
                    el = self.elig[sides] = self.eligible(sides)
                cool, awake, pred = self.cool, s.awake, self.pred
                out = []
                for h, mine in el:
                    if cool.get(h, -1) > rnd or h in claimed or h in awake:
                        continue
                    if not mine and not self.pred_ok(h, s.hp, keep):
                        continue
                    if fuel() - RESERVE < SCORE_FUEL:
                        break
                    value, r, dmg = self.static_of(h)
                    p = self.pred.get(h)
                    if p is not None:                              # exact: must leave keep_hp at THIS hp (I3)
                        r, dmg = p[0], p[1]
                        if r >= FAR or dmg * SOLO_SAFETY >= s.hp - keep:
                            continue
                    elif r >= FAR or s.hp < LOW_HP_PICK * s.max_hp or \
                            (plan is None and dmg * SOLO_SAFETY >= s.hp - keep):
                        continue
                    d = w.dist(h, pos)
                    if d is None:
                        d = pos.chebyshev_distance(w.anchor[h])
                    if d >= FAR:
                        continue
                    a = w.anchor[h]
                    if fresh and any(q.chebyshev_distance(a) <= GROUP_SIGHT for q in fresh):
                        continue                                   # a stronger enemy stands there: ClearCamp would fail `enemy`
                    sc = value / (d + r + CAP_FIXED)
                    if seen and any(q.chebyshev_distance(a) <= SIGHT_R + 2 for q in seen):
                        sc *= SIGHT_DISCOUNT                       # P9: march through empty country
                    out.append((sc, h))
                return out

            def choose(self, s):
                w = self.w
                if s.hp < self.c("recall_hp") * s.max_hp and not w.spawn.is_set(s.pos):
                    return GoHome("heal"), "lowhp"
                if s.bag >= self.c("bank_at"):                     # a full bag banks before any new clear (review)
                    i = self.bank_target(s)
                    if i is not None:
                        return Bank(i), "bag"
                    if not w.spawn.is_set(s.pos) and s.rnd - self.home_r > BANKHOME_REST:
                        return GoHome("bank"), "bag"
                pt = pair_choice(self, s)                          # 67_group: a group take for the Guard / partner
                if pt is not None:
                    return pt, "pair"
                claimed = self.claimed()
                while self.route:                                  # the draft's opening route first (P1: planned)
                    h = self.route.pop(0)
                    if h in w.groups and self.cool.get(h, -1) <= s.rnd and h not in claimed \
                            and h not in s.awake and w.dist(h, s.pos) != FAR:
                        return ClearCamp(h), "route"
                cs = self.candidates(s)
                if cs:
                    sc, h = max(cs)
                    return ClearCamp(h), f"score={sc:.2f}"
                if s.bag > 0:
                    i = self.bank_target(s)
                    if i is not None:
                        return Bank(i), "no_group"
                if (s.hp < s.max_hp or s.gold >= 30) and not w.spawn.is_set(s.pos):
                    return GoHome("heal" if s.hp < s.max_hp else "shop"), "no_group"
                soon = []
                for h, u in self.cool.items():
                    if u > s.rnd and h not in claimed and self.solo_ok(h):
                        d = w.dist(h, s.pos)
                        d = s.pos.chebyshev_distance(w.anchor[h]) if d is None else d
                        if d < FAR:
                            soon.append((max(u - s.rnd, d), u, h))
                if soon:                                           # P15: be where the next camp will be
                    _, u, h = min(soon)
                    wr = WaitRespawn(h, u)
                    wr.dec = self
                    return wr, "respawn"
                i = self.altar_key(s)
                st = Station("altar" if i is None else f"a{i}")
                st.dec = self                                      # re-checks for work without ending (no churn)
                return st, "nothing"

            # ------------------------------------------------------------ one turn
            def tick(self, s):
                w = self.w
                sense(w, s)
                deny_watch(w, s)                                   # 66_deny: did last round's deny work
                self.update_role(s)
                self.watch_claims(s)
                self.watch_threats(s)
                self.update_risk(s)
                self.deny_now = False
                r = pair_filter(self, s, self.interrupts(s))       # 67_group drops rows a GroupTake handles itself
                if r is not None:
                    evn, nt, pause, text = r
                    self.fired[evn] = self.fired.get(evn, 0) + 1
                    ev("int", f"{evn} {text}")
                    t = self.task
                    if evn == "DENY" and self.deny_now and self.paused is not None and t is not None \
                            and t.status == "run":
                        return self.inline(s, nt)                  # a task is paused already: deny without ending t
                    if t is not None and t.status == "run":
                        if pause and self.paused is None:
                            self.paused = t
                        else:
                            t.abort(w, s, evn.lower())
                            self.after_end(t, s)
                    self.task = nt
                    if nt is not None:
                        nt.start(w, s)
                act_ = "wait why=blocked"
                fresh = 0                                          # tasks started this turn that need a new field
                for i in range(3):                                 # a task that ends without acting hands on the turn
                    t = self.task
                    if t is None and self.paused is None and (fresh or (i and fuel() - RESERVE < REPICK_FUEL)):
                        break                                      # one new leg per turn; re-pick next turn (I9)
                    if t is None:
                        if self.paused is not None:
                            t, self.paused = self.paused, None
                            if isinstance(t.key, int) and self.cool.get(t.key, -1) > s.rnd and not isinstance(t, WaitRespawn):
                                t.abort(w, s, "captured")          # its group was taken meanwhile: a fresh choice
                                continue
                            if isinstance(t.key, int) and t.key in self.claimed() and not isinstance(t, GroupTake):
                                t.abort(w, s, "ally_on")           # I5: an ally claimed it while we were away
                                self.after_end(t, s)
                                continue
                            ev("int", f"RESUME {t.name} g={gid(t.key)}")
                        else:
                            t, why = self.choose(s)
                            t.start(w, s)
                            fresh += t.key not in w.fields
                        self.task = t
                    t.act = "wait why=blocked"                     # never a stale act from an earlier turn
                    st = t.step(w, s)
                    act_, self.fight, self.hit = t.act, t.fight, t.hit
                    if t.then is not None:                         # ClearCamp ok: its Capture already stepped
                        self.after_end(t, s)
                        nt, t.then = t.then, None
                        if nt.status == "run":
                            self.task = nt
                        else:                                      # it ended on its first step (danger, ally_on)
                            self.after_end(nt, s)
                            self.task = None
                        break
                    if st != "run":
                        self.after_end(t, s)
                        self.task = None
                        if self.nav.moved_round == s.rnd or not act_.startswith("wait"):
                            break
                        continue
                    break
                if self.nav.moved_round == s.rnd and "mv" not in act_:     # Nav moved: the act says so (I14)
                    act_ = "mv" if act_.startswith("wait") else f"mv,{act_}"
                self.blk = self.blk + 1 if act_.startswith("wait why=blocked") else 0
                t = self.task
                self.key = t.key if t is not None else (self.paused.key if self.paused is not None else None)
                self.fight = None if self.fight == "-" else self.fight
                self.hit = None if self.hit == "-" else self.hit
                self.ticked = True
                self.hp_prev = s.hp
                return act_ or "wait why=blocked"

            def inline(self, s, nt):
                """Row 5b when a task is already paused: run the Deny this turn (it lands now: turns == 0) without
                ending the running task, which steps again next turn."""
                w = self.w
                nt.start(w, s)
                nt.act = "wait why=blocked"
                st = nt.step(w, s)
                if st == "run":
                    nt.abort(w, s, "inline")                       # one turn only: the running task resumes next turn
                act_ = nt.act or "wait why=blocked"
                if self.nav.moved_round == s.rnd and "mv" not in act_:
                    act_ = "mv" if act_.startswith("wait") else f"mv,{act_}"
                self.fight, self.hit = None, None
                self.blk = 0
                self.ticked = True
                self.hp_prev = s.hp
                return act_

            def after_end(self, t, s):
                """Bookkeeping of an ended task: group cooldowns, and event 8 (Bank found an enemy lock: I13)."""
                h, why = t.key, (t.why or "").split(":")[0]
                if isinstance(t, Capture) and t.status == "ok":
                    try:
                        self.cool[h] = s.rnd + self.w.groups[h].max_respawn_timer()
                    except Exception:
                        self.cool[h] = s.rnd + 40
                    self.cool_why.pop(h, None)                     # resting for its timer, not for danger
                elif isinstance(h, int) and t.status != "ok" and not isinstance(t, WaitRespawn):
                    c = s.rnd + COOL.get(why, 10)
                    if c > self.cool.get(h, -1):
                        self.cool[h] = c
                        self.cool_why[h] = why
                if isinstance(t, GoHome) and t.status == "ok":
                    self.home_r = s.rnd                            # no BANKHOME churn: home -> ClearCamp -> home
                if isinstance(t, Bank):
                    if t.status == "ok":
                        self.bank_bad.pop(t.key, None)
                    elif why in ("evade", "flee", "enemy"):
                        n = self.bank_bad.get(t.key, 0) + 1
                        if n >= BANK_BAD_N:                        # twice chased off this altar: bank elsewhere or home
                            n = 0
                            self.skip[("Bank", t.key)] = s.rnd + BANK_AVOID
                            ev("int", f"BANKAVOID altar={t.key} r={BANK_AVOID}")
                        self.bank_bad[t.key] = n
                if isinstance(t, ClearCamp) and why == "respawning" and isinstance(h, int):
                    tm = self.resp_timer(h)                        # [sdk] CampGroupRespawning.timer: rest exactly that
                    if tm is not None:
                        self.cool[h] = s.rnd + tm + 1
                        if tm <= RESP_WAIT and self.paused is None and w_d(self.w, h, s) <= 3:
                            wr = WaitRespawn(h, s.rnd + tm + 1)
                            wr.dec = self
                            wr.start(self.w, s)
                            self.paused = wr                       # be on the ring when it respawns (P15)
                if isinstance(t, Bank) and t.status != "ok" and why not in ("died", "locked") \
                        and self.skip.get(("Bank", t.key), -1) < s.rnd + BANK_SKIP:
                    # L5 commitment: a Bank that failed (enemy at the altar, stuck, broken) or was pre-empted (flee)
                    # is not re-picked for that altar for BANK_SKIP rounds; bank_target picks another or none.
                    self.skip[("Bank", t.key)] = s.rnd + BANK_SKIP
                nt = how = None
                if isinstance(t, Bank) and why == "locked" and self.paused is None:
                    # Row 8 (I13): clear the lock if it is safe, else rest that altar and bank elsewhere.
                    safe = not any(e[0].chebyshev_distance(s.pos) <= R1 + 3 for e in s.enemies)
                    if safe:
                        nt, how = ClearLock(t.i), "clear"
                    else:
                        self.skip[("Bank", t.key)] = s.rnd + BANK_SKIP
                        i = self.bank_target(s)
                        nt, how = (Bank(i), "retarget") if i is not None else (None, None)
                elif isinstance(t, ClearLock) and self.paused is None and s.alive and s.bag > 0 and why != "died":
                    if t.status == "ok":
                        nt, how = Bank(t.i), "bank"                # the lock is gone: bank there at once
                    else:
                        self.skip[("Bank", t.key)] = s.rnd + BANK_SKIP
                        i = self.bank_target(s)
                        nt, how = (Bank(i), "retarget") if i is not None else (None, None)
                if nt is not None:
                    ev("int", f"LOCK altar={t.key} {how}")
                    self.fired["LOCK"] = self.fired.get("LOCK", 0) + 1
                    nt.start(self.w, s)
                    self.paused = nt                               # runs next in this tick's loop
                pair_after_end(self, t, s)                         # 67_group: the mate captures -> the group rests

            # ------------------------------------------------------------ housekeeping and bookkeeping
            def shop(self, s):
                return shop_turn(self.w, s)

            def task_name(self):
                return self.task.name if self.task is not None else "-"

            def death_cause(self):
                s = self.w.snap
                return "champ" if s is not None and _S["seen"] and _S["seen"][-1][0] >= s.rnd - 2 else "camp"

            def died(self, s):
                for t in (self.task, self.paused):
                    if t is not None and t.status == "run":
                        t.abort(w=self.w, s=s, why="died")
                self.task = self.paused = None
                self.key = self.fight = self.hit = None
                self.hp_prev = None                                # a respawn is not a hit (event 3)
                self.report()

            def report(self):
                if self.fired:
                    trace("ints", " ".join(f"{k}={v}" for k, v in sorted(self.fired.items())))

            def work(self):
                """Background: one exact solo-clear prediction per group (full HP, cooldowns ready), nearest first,
                after the field queue, each only if its self-corrected cost fits under the reserve (I9)."""
                n, f0 = 0, fuel()
                w = self.w
                while self.sq and fuel() - RESERVE - BG_MARGIN > STATIC_FUEL:
                    self.static_of(self.sq.pop(0))                 # candidates' static values (60-90k each, once)
                    n += 1
                while self.pq and not w.queue and fuel() - RESERVE - BG_MARGIN > self.pcost:
                    h = self.pq.pop(0)
                    f1, r1 = fuel(), cambc.round_number()
                    comp = [(m[1], m[2], m[3], m[4]) for m in group_comp(w, h)]
                    p = predict_clear(self.kit, comp, (0, 0), True) if comp else None
                    if p is not None:
                        self.pred[h] = p
                    c = int(spent(f1, r1) * 1.3)
                    if c > self.pcost * 1.3:
                        trace("fuel", f"over est={self.pcost} job=pred{h} cost={c * 10 // 13}")
                    if c > self.pcost:
                        self.pcost = c
                    n += 1
                if not w.queue:
                    n += pair_work(self)[0]                        # 67_group: pair predictions best_pair asked for
                return n, f0 - fuel()


_LAZY.append(('70_decide', 888, _lazy_70_decide))

# ---- 80_team.py (lazy: runs when 90_main calls _lazy_80_team) ----
def _lazy_80_team():
    global LEAD_EVERY, SOS_R, TEAM_LOG, TeamCard, TeamView, _stunner, _team_claims, _team_log_view, _team_log_write, _team_posture, _team_roles, _team_setup
    global _wants_help, team_begin, team_claim, team_commit, team_make_mem, team_roles, team_task
    # tzu: lazy
    """L6 Team: the 8 shared bytes read once and written once per turn, and the role function on the alive mask.
    Spec: docs/design/MEMORY_LAYOUT.md §2 (both variants, one interface: 10_mem.SharedMem), ROLES_AND_LAYERS.md
    §1.4 (re-assignment) and L6 (done when: 0 double-claims, re-assignment within 1 round of a death, < 20k fuel).

        team_begin(w, s)          skeleton step 2, every turn after the snapshot (dead turns too)  -> w.team
        team_commit(w, s, task)   skeleton step 6, every turn incl. dead and crashed turns (the heartbeat)
        team_task(dec)            the task to claim from: the running task, else the paused one

    w.team (a TeamView), valid after team_begin:
        ready            False until SharedMem exists (plan decoded, World stage 2); then everything below is set
        variant          "A" or "B" (the draft's choice: header flag PF_MEM_B; 10_mem.mem_variant_of)
        slot, alive_mask my draft slot; bit i = slot i beat on its last turn (heartbeat, 10_mem SharedMem.begin)
        roles            {slot: role id} = team_roles(alive_mask, cards); my_role, my_card (Card or TeamCard),
                         guard (slot of the acting Guard or None); role_changed (this turn)
        claims           [code per slot 0-4]: handle 0-59, CLAIM_BANK/HUNT/OUT/NONE (NONE for dead or unused slots)
        capturing        [bool per slot] (A: the stored bit; B: None, not stored)
        claimed_groups   handles claimed by an alive ally (not me): ClearCamp/Capture/GroupTake/WaitRespawn targets
        capturing_groups handles an alive ally is capturing: A the status bit; B = claimed_groups (MEMORY §2.3: never
                         enter the spawn region of a group an alive ally claims; stronger, still 0 joined captures)
        sighting         None or (x, y, age, bag_bucket, flags): A bucket 1 small / 2 big (>= G_RISK), flags 0;
                         B bucket 0-3, flags bit 0 stunner, 1 several, 2 SOS. Position error: A <= 2, B <= 1 tile
                         (sight_err); readers add it to their radius
        help             None or (target, age, sos): target a group handle (group take) or (x, y) (SOS);
                         help_from = the alive ally slot whose claim is that handle (the requester), else None
        posture          FARM / DEFEND / HUNT / REGROUP (A derived here, B stored by the acting Guard)

    Writes (team_commit), MEMORY_LAYOUT §2.1: my claim from the task; my sighting (the biggest bag in sight, then
    the nearest) with bag bucket, stunner and several flags; SOS when I carry >= bank_at_threat with an enemy
    within R1 + 2 (A: help code 61; B: the sighting's SOS bit); a group-take help request while a GroupTake task
    says wants_help (A: byte 7, never over an ally's fresh request; B: the Guard only, bit 7 + its claim);
    B: the acting Guard writes the posture; B linked bag for Cassi & Issac. Then SharedMem.commit (heartbeat).

    GroupTake contract (67_group.py): key = the group handle, wants_help (bool or method), capturing (bool).

    Variant B bot for the arena (one source serves both; the draft writes the flag, every champion obeys it):
        python -I tools/assemble.py
        mkdir -p bots/tzu_b/src && sed 's/^MEM_VARIANT = "A"/MEM_VARIANT = "B"/' bots/tzu/src/main.py \
            > bots/tzu_b/src/main.py && cp bots/tzu/pyrightconfig.json bots/tzu_b/
        python -I tools/arena.py tzu tzu_b
    TEAM_LOG = True adds the tm| lines the team test reads (claims, views, sightings, fuel); off in play.
    Fuel [measured 13 Oct, mirrors on collision/lanes/corners, TEAM_LOG on]: begin+commit ~55k on a turn where
    only heartbeats moved (read ~10k, 1-byte write ~5k, the rest Python at ~1-3k a line), ~100k when an ally's
    sighting or claim changed, ~200k on turns I write a sighting myself; game average 95-150k. The L6 target
    (< 20-25k) is below the engine floor of one read + one write plus the glue; see the report.
    """

    if not cambc.is_draft():
        TEAM_LOG = False                # tm| trace lines (test builds); off: they cost fuel and replay stdout
        SOS_R = 7                       # R1 + 2: an enemy this close to a carrier makes an SOS (MEMORY §2.1, A45)
        LEAD_EVERY = 10                 # rounds between global_submitted_gems reads (Variant A's derived posture)

        class TeamCard:
            """A role card for a role the draft did not write for this slot (re-assignment after a death): the
            role's CARD_DEFAULTS (40_draft, module level) over the slot's own card (home altar, rank, partner, ward
            duty kept; no route: the opening route belongs to the planned role). Same field names as 10_mem.Card."""

            def __init__(self, role, base):
                if base is not None:
                    for k in Card.__slots__:
                        setattr(self, k, getattr(base, k, None))
                else:
                    self.slot, self.ctype, self.home_altar, self.ward_duty, self.ward_target = None, 255, 255, 0, 255
                    self.partner, self.guard_rank = 7, 7
                d = CARD_DEFAULTS.get(role if role != ROLE_LONE else ROLE_FARMER, CARD_DEFAULTS[ROLE_FARMER])
                for k, v in d.items():
                    setattr(self, k, v)
                if role == ROLE_LONE:
                    self.bank_at, self.sides = 20, 1                 # ROLES §1.4 Lone [provisional A15]
                self.role = role
                self.route = []

            def get(self, k, default=None):
                return getattr(self, k, default)

        def team_roles(am, cards):
            """ROLES_AND_LAYERS §1.4, pure in (alive mask, cards): every champion reaches the same answer.
            Hunter (role 3) is never re-assigned and never takes the Guard card. All alive (or none): the plan.
            One alive non-Hunter: Lone. One dead in a 4-5 team: the Flex covers a dead Guard, else unchanged.
            Otherwise: the planned Guard if alive, else the best Guard rank among the alive non-Hunters guards
            (unless it would be the only one left: it farms), the other non-Hunters farm."""
            slots = [i for i in range(len(cards)) if cards[i] is not None]
            plan = {i: cards[i].role for i in slots}
            out = dict(plan)
            alive = [i for i in slots if am >> i & 1]
            if not alive or len(alive) == len(slots):
                return out
            pool = [i for i in alive if plan[i] != ROLE_HUNTER]
            if len(alive) == 1:
                if pool:
                    out[pool[0]] = ROLE_LONE
                return out
            guard = [i for i in pool if plan[i] == ROLE_GUARD]
            if len(slots) - len(alive) == 1 and len(slots) >= 4:
                if guard:
                    return out
                flex = [i for i in pool if plan[i] == ROLE_FLEX]
                if flex:
                    out[flex[0]] = ROLE_GUARD
                    return out
            if len(pool) == 1:
                i = pool[0]
                out[i] = ROLE_GUARD if plan[i] == ROLE_GUARD else ROLE_FARMER
                return out
            g = guard[0] if guard else min(pool, key=lambda i: (cards[i].guard_rank, i))
            for i in pool:
                out[i] = ROLE_GUARD if i == g else ROLE_FARMER
            return out

        class TeamView:
            def __init__(self):
                self.ready = False
                self.variant = MEM_VARIANT
                self.slot = None
                self.cards = []
                self.alive_mask = 31
                self.roles = {}
                self.my_role, self.my_card, self.guard = ROLE_FARMER, None, None
                self.role_changed = False
                self.claims = [CLAIM_NONE] * 5
                self.capturing = [False] * 5
                self.claimed_groups = self.capturing_groups = frozenset()
                self.sighting = self.help = self.help_from = None
                self.posture = FARM
                self.sight_err = 2
                self.home = None                # home altar (x, y) for the derived posture
                self._am = None                 # alive mask the roles were computed for
                self._rcache = {}               # alive mask -> (roles, priorities)
                self._prio = None
                self._ckey = None               # (claim bits, alive mask) the claims were decoded for
                self._lead, self._lead_r = 0, -LEAD_EVERY
                self._base = FARM               # posture from the lead alone (A, between lead reads)
                self._sf, self._sr = 0, None    # sighting field last decoded, and (x, y, stamp round, bucket, flags)
                self._hr = 0                    # round t.help was last decoded or aged
                self._stun = {}                 # enemy ChampionType -> has a stun (sighting flag, I13)
                self.fb = self.fc = 0           # fuel of this turn's begin / commit
                self.fsum = self.fmax = self.fn = self.fbs = 0
                self._log = {}

        def team_make_mem(w):
            """SharedMem for my slot with the plan's posture block and the variant the draft chose."""
            plan = w.plan if w.plan_ok else None
            slot = plan.slot_of(w.ctype) if plan is not None else None
            if slot is None:                    # no plan: rank of my type among the allies in sight on spawn
                try:
                    ts = sorted({int(c.champion_name()) for c in vision.champions(Team.ALLY)} | {w.ctype})
                    slot = min(ts.index(w.ctype), 4)
                except Exception:
                    slot = w.ctype % 5
            kw = {}
            if plan is not None and plan.posture is not None:
                p = plan.posture
                kw = dict(sight_ttl=p.sight_ttl or 10, help_ttl=p.help_ttl or 3, g_risk=p.g_risk or 20,
                          defend_r=p.defend_r or 10, hunt_lead=p.hunt_lead or 10)
                card = plan.card_for(w.ctype)
                if card is not None and card.home_altar != 255 and card.home_altar < len(plan.altars):
                    a = plan.altars[card.home_altar]
                    kw["home_altar"] = (a.x, a.y)
            return SharedMem(slot, w.W, w.H, variant=mem_variant_of(plan), linked=w.ctype in (3, 4),
                             ctype=w.ctype, **kw)

        def _team_setup(w, t, m):
            t.ready = True
            t.variant = m.variant
            t.slot = m.slot
            t.sight_err = 2 if m.variant == "A" else 1
            t.home = m.home_altar
            plan = w.plan if w.plan_ok else None
            if plan is not None:
                t.cards = [plan.cards[i] for i in range(min(plan.team_size, MAX_SLOTS))]
                # stunner flags from the draft's enemy profiles (§1.4); unknown types are looked up on sight
                for e in range(5):
                    r = plan.enemies[e]
                    if r is not None:
                        t._stun[r.ctype] = r.stun

        def _team_roles(w, t, m, rnd):
            am = m.amask
            if am == t._am:
                t.role_changed = False
                return
            t._am = am
            r = t._rcache.get(am)
            if r is None:
                cards = t.cards
                if cards and t.slot is not None and t.slot < len(cards) and cards[t.slot] is not None:
                    roles = team_roles(am, cards)
                    prio = tuple(cards[i].priority if roles.get(i) == cards[i].role
                                 else CARD_DEFAULTS.get(roles.get(i), CARD_DEFAULTS[ROLE_FARMER])["priority"]
                                 if roles.get(i) != ROLE_LONE else 0
                                 for i in range(len(cards)) if cards[i] is not None)
                else:
                    roles, prio = {}, None
                r = t._rcache[am] = (roles, prio)
            roles, prio = r
            t.roles = roles
            g = [i for i, ro in roles.items() if ro == ROLE_GUARD and am >> i & 1]
            t.guard = g[0] if g else None
            role = roles.get(t.slot, ROLE_FARMER) if roles else ROLE_FARMER
            if prio != t._prio:
                if t._prio is not None:
                    m.reorder(rnd)          # the within-team order changes next round: hold the alive bits
                t._prio = prio
            if role != t.my_role or t.my_card is None:
                base = t.cards[t.slot] if t.cards and t.slot is not None and t.slot < len(t.cards) else None
                old = t.my_role
                t.my_role = role
                t.my_card = base if base is not None and base.role == role else (
                    TeamCard(role, base) if base is not None else None)
                t.role_changed = True
                if t.my_card is not None:
                    try:
                        w.me.set_priority(int(t.my_card.priority))   # takes effect next round [rules]
                    except Exception:
                        pass
                if TEAM_LOG:
                    trace("tm", f"role {old}->{role} mask={am}")
            else:
                t.role_changed = False

        def _team_claims(t, m, v, am):
            """Decode the claim word from the bytes just read (small-int arithmetic: a 64-bit int op costs several
            k in the engine [measured 13 Oct], a byte op ~0.2k). Claim i = bits 6i..6i+5 of the u32 at byte 3 (A)
            or 4 (B); A's status bits: byte 0 bits 5-7 (slots 0-2), the u32's bits 30-31 (slots 3-4)."""
            D = CLAIM_DEC
            N = CLAIM_NONE
            buf = m.buf
            o = 3 if m.cbit >= 0 else 4
            b0, b1, b2, b3 = buf[o], buf[o + 1], buf[o + 2], buf[o + 3]
            c0 = D[b0 & 63] if am & 1 else N
            c1 = D[(b0 >> 6 | b1 << 2) & 63] if am & 2 else N
            c2 = D[(b1 >> 4 | b2 << 4) & 63] if am & 4 else N
            c3 = D[b2 >> 2] if am & 8 else N
            c4 = D[b3 & 63] if am & 16 else N
            codes = [c0, c1, c2, c3, c4]
            me = t.slot
            cg = set(codes)
            if me is not None:
                cg.discard(codes[me])
                for i in range(5):          # my own code must not hide an ally's identical claim
                    if i != me and codes[i] == codes[me]:
                        cg.add(codes[i])
            cg.discard(N)
            cg.discard(CLAIM_BANK)
            cg.discard(CLAIM_HUNT)
            cg.discard(CLAIM_OUT)
            t.claims = codes
            t.claimed_groups = cg
            if o == 3:
                cb = buf[0] >> 5 | (b3 >> 6) << 3
                if cb:
                    capt = [bool(cb & 1) and c0 >= 0, bool(cb & 2) and c1 >= 0, bool(cb & 4) and c2 >= 0,
                            bool(cb & 8) and c3 >= 0, bool(cb & 16) and c4 >= 0]
                    t.capturing_groups = {codes[i] for i in range(5) if i != me and capt[i]}
                else:
                    capt = [False] * 5
                    t.capturing_groups = set()
                t.capturing = capt
            else:
                t.capturing = [None] * 5
                t.capturing_groups = cg

        def team_begin(w, s):
            """Skeleton step 2. Creates SharedMem once the plan is decoded (World stage 2); before that, a raw
            read into s.mem only. Every field of w.team is this turn's. Decodes only what changed since my last
            turn (claims, sighting, help); the common turn is the read, the heartbeat and a few compares."""
            f0 = fuel() if TEAM_LOG else 0
            m = w.mem
            if m is None:
                t = getattr(w, "team", None)
                if t is None:
                    t = w.team = TeamView()
                if w.stage != 2:
                    buf = bytearray(8)
                    cambc.shared_memory.read(0, buf)
                    s.mem = int.from_bytes(buf, "little")
                    return t
                m = w.mem = team_make_mem(w)
                _team_setup(w, t, m)
            try:
                t = w.team
            except AttributeError:          # SharedMem made elsewhere (old step-2 hook): adopt it
                t = w.team = TeamView()
                _team_setup(w, t, m)
            rnd = s.rnd
            v = s.mem = m.begin(rnd)
            am = t.alive_mask = m.amask
            if am != t._am:
                _team_roles(w, t, m, rnd)
                t._ckey = None
            elif t.role_changed:
                t.role_changed = False
            full = t._ckey is None
            if full or m.ch_claims:         # decode only the fields whose bytes moved (SharedMem.begin)
                t._ckey = 1
                _team_claims(t, m, v, am)
            if full or m.ch_sight:          # the sighting from the bytes (small ints), = SharedMem.sighting()
                buf = m.buf
                if m.cbit >= 0:
                    f = buf[1] | buf[2] << 8
                else:
                    f = buf[1] | buf[2] << 8 | buf[3] << 16
                if f:
                    qb, sm = m.QB, m.SMASK
                    st = f >> m.STS & sm
                    q = (1 << qb) - 1
                    if m.cbit >= 0:
                        bk, fl = (2 if f >> 15 else 1), 0
                    else:
                        bk, fl = f >> 18 & 3, f >> 20 & 7
                    t._sr = ((f & q) * m.cx + (m.cx >> 1), (f >> qb & q) * m.cy + (m.cy >> 1),
                             rnd - ((rnd - st) & sm), bk, fl)
                else:
                    t._sr = None
            if full or m.ch_help or ((m.ch_claims or m.ch_sight) and t.help is not None):
                if (v >> 56 & 63) if m.variant == "A" else (v & 0x80 or v >> 30 & 1):
                    hp = t.help = m.help(t.guard)
                    t._hr = rnd
                    t.help_from = None
                    if hp is not None and not hp[2]:
                        for i in range(5):
                            if i != t.slot and t.claims[i] == hp[0]:
                                t.help_from = i
                                break
                else:
                    t.help = t.help_from = None
            elif t.help is not None and rnd != t._hr:   # unchanged bytes: age it; stamped requests expire
                hp = t.help
                age = hp[1] + rnd - t._hr
                if (m.variant == "A" or hp[2]) and age >= m.help_ttl:
                    t.help = t.help_from = None
                else:
                    t.help = (hp[0], age, hp[2])
                    t._hr = rnd
            r = t._sr                       # the sighting's age moves every round; its bytes don't
            if r is None or rnd - r[2] > m.sight_ttl:
                t.sighting = None
            else:
                t.sighting = (r[0], r[1], rnd - r[2], r[3], r[4])
            if m.variant == "B":
                g = t.guard
                t.posture = v >> 5 & 3 if g is not None and am >> g & 1 else FARM
            elif t.sighting is not None or t.help is not None or rnd - t._lead_r >= LEAD_EVERY:
                t.posture = _team_posture(t, m, rnd)
            else:
                t.posture = t._base
            if TEAM_LOG:
                t.fb = f0 - fuel()
                _team_log_view(t, rnd)
            return t

        def _team_posture(t, m, rnd):
            """MEMORY §2.2 derived posture (A every turn; B the acting Guard writes it)."""
            if t.help is not None:
                return DEFEND
            sg, h = t.sighting, t.home
            if sg is not None and sg[3] >= 2 and h is not None and \
                    max(abs(sg[0] - h[0]), abs(sg[1] - h[1])) <= m.defend_r + t.sight_err:
                return DEFEND
            if rnd - t._lead_r >= LEAD_EVERY:
                t._lead_r = rnd
                try:
                    t._lead = cambc.global_submitted_gems(Team.ALLY) - cambc.global_submitted_gems(Team.ENEMY)
                except Exception:
                    t._lead = 0
            t._base = HUNT if t._lead >= m.hunt_lead else FARM
            return t._base

        def team_task(dec):
            """The task whose target I claim: the running task; when it claims nothing (Flee, StepOff, a heal
            walk, Reach...), the paused one, so a group I will resume stays mine (a released claim let an ally
            take it and both cleared it [measured: mirror, collision, 13 Oct]). Hunt/Bank claims win over it, and a
            paused group an ally has claimed since is not re-claimed (the Decider's resume check drops it)."""
            if dec is None:
                return None
            t = getattr(dec, "task", None)
            p = getattr(dec, "paused", None)
            run = t is not None and getattr(t, "status", "run") == "run"
            if run and (p is None or team_claim(t)[0] != CLAIM_NONE):
                return t
            if p is not None:
                tm = getattr(dec.w, "team", None)
                if tm is not None and getattr(p, "key", None) in tm.claimed_groups and type(p).__name__ != "GroupTake":
                    return t if run else None   # an ally took it while I was away: don't re-claim (resume yields)
            return p

        def team_claim(task):
            """(code, capturing) for a task, by class name (65_hunt redefines Hunt; 67_group adds GroupTake)."""
            if task is None or getattr(task, "status", "run") != "run":
                return CLAIM_NONE, False
            n = type(task).__name__
            k = getattr(task, "key", None)
            if n in ("ClearCamp", "Capture", "GroupTake", "WaitRespawn") and isinstance(k, int):
                if n == "Capture":
                    return k, getattr(task, "on", None) is not None
                if n == "GroupTake":
                    return k, bool(getattr(task, "capturing", False))
                return k, False
            if n in ("Bank", "ClearLock"):
                return CLAIM_BANK, False
            if n in ("Hunt", "Hold", "Deny"):
                return CLAIM_HUNT, False
            if n == "GoHome" and getattr(task, "rec", False):
                return CLAIM_OUT, False
            return CLAIM_NONE, False

        def _wants_help(task):
            if task is None or type(task).__name__ != "GroupTake" or getattr(task, "status", "run") != "run":
                return None
            wh = getattr(task, "wants_help", False)
            if callable(wh):
                wh = wh()
            k = getattr(task, "key", None)
            return k if wh and isinstance(k, int) else None

        def _stunner(t, c):
            try:
                ct = int(c.champion_name())
            except Exception:
                return True
            r = t._stun.get(ct)
            if r is None:
                try:
                    r = bool(kit_of(ct).stunner)          # L3, Champion.design once per type
                except Exception:
                    r = True                              # unknown: the safe side (I13)
                t._stun[ct] = r
            return r

        def team_commit(w, s, task):
            """Skeleton step 6, every turn (dead and crashed turns too). Returns bytes written (-1: no memory)."""
            f0 = fuel() if TEAM_LOG else 0
            m = w.mem
            t = getattr(w, "team", None)
            if m is None or t is None or not t.ready:
                return -1
            sw = None
            if s.alive:
                code, capt = team_claim(task)
                sos = False
                en = s.enemies
                if en:
                    pos = s.pos
                    best, bk, near = None, None, 999
                    for e in en:
                        d = max(abs(e[0].x - pos.x), abs(e[0].y - pos.y))
                        if d < near:
                            near = d
                        k = (e[2], -d)
                        if bk is None or k > bk:
                            best, bk = e, k
                    c = t.my_card
                    bat = c.bank_at_threat if c is not None else m.g_risk
                    sos = s.bag > 0 and s.bag >= bat and near <= SOS_R
                    p = best[0]
                    if m.set_sighting(p.x, p.y, best[2], stunner=_stunner(t, best[3]), several=len(en) > 1, sos=sos):
                        sw = (p.x, p.y, best[2], int(sos))
                want = _wants_help(task) if code >= 0 else None
                if m.variant == "A":
                    if sos:
                        m.set_help(sos=True)
                    elif want is not None:
                        hp = t.help
                        mine = m.my_help != 0 and m.nv >> 56 & 63 == m.my_help
                        if hp is None or mine:
                            m.set_help(target=want)
                    elif m.my_help:
                        m.clear_help()
                else:
                    if want is not None and t.my_role == ROLE_GUARD and code == want:
                        m.set_help()
                    elif m.my_help:
                        m.clear_help()
                    if t.my_role == ROLE_GUARD and t.guard == t.slot:
                        m.set_posture(_team_posture(t, m, s.rnd))
                    if m.linked:
                        m.set_linked_bag(s.bag)
                n = m.commit(True, code, capt, cambc.round_number())
            else:
                n = m.commit(False, now=cambc.round_number())
            if TEAM_LOG:                    # fuel of begin + commit, measured only in test builds (fuel() ~1.8k)
                t.fc = f0 - fuel()
                f = t.fb + t.fc
                t.fsum += f
                t.fbs += t.fb
                t.fn += 1
                if f > t.fmax:
                    t.fmax = f
                h = t._log.setdefault("hist", [0] * 12)       # [<30k <60k <100k <200k >=200k] x (quiet, contact)
                k = 0 if f < 30000 else 1 if f < 60000 else 2 if f < 100000 else 3 if f < 200000 else 4
                j = 6 if s.enemies else 0
                h[j + k] += 1
                h[j + 5] += f
                _team_log_write(t, m, s, sw)
            return n

        # ---------------------------------------------------------------- test lines (TEAM_LOG)
        def _team_log_view(t, rnd):
            sg = t.sighting
            sk = None if sg is None else (sg[0], sg[1], rnd - sg[2], sg[3], sg[4])
            hp = t.help
            hk = None if hp is None else (hp[0], rnd - hp[1], hp[2])
            key = (t.alive_mask, tuple(t.claims), tuple(t.capturing), sk, hk, t.posture)
            if key != t._log.get("v"):
                t._log["v"] = key
                ss = "-" if sg is None else f"{sg[0]},{sg[1]},{sg[2]},{sg[3]},{sg[4]}"
                hs = "-" if hp is None else f"{hp[0]},{hp[1]},{int(hp[2])}"
                cap = "".join("1" if c else "0" for c in t.capturing)
                trace("tm", f"view m={t.alive_mask} c={','.join(map(str, t.claims))} cap={cap} s={ss} h={hs} "
                            f"p={t.posture} role={t.my_role} slot={t.slot}")

        def _team_log_write(t, m, s, sw):
            code = m.nv >> (m.CL + 6 * m.slot) & 63
            key = (code, s.alive)
            if key != t._log.get("w"):
                t._log["w"] = key
                trace("tm", f"claim raw={code} alive={int(s.alive)} slot={m.slot}")
            if sw is not None:
                trace("tm", f"sw {sw[0]},{sw[1]} bag={sw[2]} sos={sw[3]}")
            if s.rnd % 250 == 0 or s.rnd >= 1999:
                if t.fn:
                    h = t._log.get("hist", [0] * 12)
                    trace("tm", f"fuel avg={t.fsum // t.fn} begin={t.fbs // t.fn} max={t.fmax} n={t.fn} "
                                f"last={t.fb}+{t.fc} quiet={h[0:5]} avgq={h[5] // max(1, sum(h[0:5]))} "
                                f"contact={h[6:11]} avgc={h[11] // max(1, sum(h[6:11]))}")


_LAZY.append(('80_team', 498, _lazy_80_team))

# ---- 90_main.py ----
"""Entry. The draft branch comes first; everything play-only is defined inside the `else` so the draft bot
never pays for it. The play loop IS the per-turn skeleton of INVARIANTS.md §3:

  1 SENSE      World.snapshot()                         (< 150k fuel)
  2 READ MEM   team_begin (80_team): the 8 shared bytes, one read (a raw read until 80_team is loaded)
  3 INTERRUPTS Decider.tick: the §2 table, one pass, first match wins
  4 TASK STEP  Decider.tick: the chosen task's step emits Nav / act() calls
  5 ACT        Nav.move is the only mover, act() the only attacker/caster (I14)
  6 HOUSEKEEP  every turn, dead ones too: shop (I7), then team_commit (claim, sighting, heartbeat)
  7 FACTS      inc, on_spawn, gstate, dead for the t line (before background: gstate is ~27k each)
  8 BACKGROUND World.work(): distance fields under the reserve; Decider.work(): clear and pair predictions
  7' TRACE     the t line, then the event lines of this round

Boot (tools/assemble.py): only the eager parts (00, 10, 20, 30, 40, 90) run at import; the lazy ones (50, 60,
65, 66, 67, 70, 80) are wrapped in loader functions (_LAZY), called in order as setup jobs (load_parts) whenever
fuel() - RESERVE covers LOAD_LINE x their code lines; each logs load|<part> fuel= lines=. Meanwhile World.setup's
stages run and the champion walks its opening route (Nav, eager). The Decider is built once every part is
loaded (DEC_FUEL); its first tick needs TICK_FUEL; until then the opening step.
The t line is written after background work so its fuel is the whole turn's (I9's bg= field).
    P|r|T|c|t|x,y <fuel> <act> tgt=<key> [bag= inc= fight= on_spawn= gstate= dead= hit=] [q=done/total]
             [+<jobs> bg=<jobs>/<bg fuel>] [snap=<fuel>]
The replay keeps only ~1 MB of stdout per team [measured], so the bracketed fields are written only when
they differ from their default (0 or -), except on a full line every FULL_EVERY rounds and until the
field queue is done (tools/invariants.py reads a missing field as its default).
"""

if cambc.is_draft():
    _dm = globals().get("draft_main")
    if _dm is not None:
        _dm()
    while True:                                        # no planner: let the engine pick (it never returns)
        cambc.end_turn()
else:
    FULL_EVERY = 100                # every field on the t line this often; else only non-default ones
    SNAP_WARN = 150_000             # snapshot budget [INVARIANTS §0]; snap= is logged when above it
    EVENTS = []                     # (tag, text) event lines of this turn, written after the t line (same round)
    LOAD_LINE = [1600]              # fuel per code line of a lazy part: 0.5-1.55k measured (13 Oct, 70_decide the
                                    # worst); raised to any worse measurement
    LAST_ROUND = 2000               # [rules]
    _MEMBUF = bytearray(8)

    def ev(tag, text):
        EVENTS.append((tag, text))

    # ------------------------------------------------------------ boot: lazy parts as setup jobs
    def load_parts(pending, force):
        """Execute the next lazy parts in order while each fits above RESERVE (force: the first one anyway,
        so loading never starves). A part that raises is logged and skipped (the bot runs without it)."""
        n = 0
        while pending:
            name, lines, loader = pending[0]
            if not (force and n == 0) and fuel() - RESERVE < LOAD_LINE[0] * lines:
                break
            f0 = fuel()
            pending.pop(0)
            try:
                loader()
                c = f0 - fuel()
                ev("load", f"{name} fuel={c} lines={lines}")
            except Exception as e:
                c = f0 - fuel()
                ev("load", f"{name} fail fuel={c} {err_text(e)}")
            if lines and 0 < c and c // lines + 1 > LOAD_LINE[0]:          # c < 0: it crossed a turn
                LOAD_LINE[0] = c // lines + 1
            n += 1
        return n

    def read_raw(s):
        cambc.shared_memory.read(0, _MEMBUF)
        s.mem = int.from_bytes(_MEMBUF, "little")

    # ------------------------------------------------------------ step 6: housekeeping
    def housekeep(w, s, dec):
        """Every turn, dead or alive: shop (I7), then my claim, sighting and heartbeat (team_commit, 80_team).
        Returns "shop" when something was bought."""
        tok = dec.shop(s) if dec is not None else None
        tc = globals().get("team_commit")
        if tc is not None:
            tc(w, s, team_task(dec))
        return tok

    def opening(w, nav):
        """Before the Decider's first tick: one step towards the first group of my route (plan decoded),
        else the map centre."""
        goal = V(w.W // 2, w.H // 2)
        if w.plan_ok:
            c = w.plan.card_for(w.ctype)
            r = [h for h in (c.route if c is not None else ()) if h in w.anchor]
            if r:
                goal = w.anchor[r[0]]
        nav.greedy(goal, sideways=True)
        return nav.act.replace("how=gr", "how=open")

    # ------------------------------------------------------------ the play loop
    def play_main():
        base_init()
        trace("boot", f"f={fuel()} type={int(cambc.me().champion_name())} lazy={len(_LAZY)}")
        w = nav = dec = None
        pending = list(_LAZY)
        was_alive, last_bag = True, 0
        q_done = False
        first = True
        idle_load = 0                                                         # turns in a row nothing loaded
        while True:
            FUEL.start()
            rnd = cambc.round_number()
            act_, jobs, bgf, sc, facts = "wait why=unknown", 0, 0, 0, None
            try:
                if w is None:
                    w = World()
                    nav = Nav(w)
                s = w.snap = w.snapshot(rnd, dec.key if dec is not None else None)   # 1 SENSE
                sc = s.cost
                if dec is None and w.setup(first) and not pending and fuel() - RESERVE > DEC_FUEL:
                    dec = Decider(w, nav)                                         # every part is loaded
                    dec.built = rnd                                               # first tick next turn (~1.6M)
                    trace("world", f"init={w.init_fuel} groups={len(w.groups)} altars={len(w.altar_pos)} "
                                   f"map={w.W}x{w.H} jobs={w.total} plan={int(w.plan_ok)} "
                                   f"route={len(dec.route)} role={dec.role}")
                tb = globals().get("team_begin")                                  # 2 READ MEM
                if tb is not None:
                    tb(w, s)
                else:
                    read_raw(s)
                if dec is None or (not dec.ticked and (dec.built == rnd or fuel() - RESERVE < TICK_FUEL)):
                    act_ = opening(w, nav) if s.alive else "wait why=dead"
                elif not s.alive:
                    if was_alive:
                        ev("death", f"gems={last_bag} task={dec.task_name()} by={dec.death_cause()}")
                        if nav.key is not None:
                            nav.end(rnd, "died")                                  # a leg can't survive a death
                        dec.died(s)
                    act_ = "wait why=dead"
                else:
                    last_bag = s.bag
                    act_ = dec.tick(s)                                            # 3 INTERRUPTS + 4 STEP + 5 ACT
                tok = housekeep(w, s, dec)                                        # 6 HOUSEKEEP
                if tok:
                    act_ = tok if act_.startswith("wait") else f"{act_},{tok}"
                first = False
                was_alive = s.alive
            except Exception as e:
                act_ = err_text(e)
                try:                                                              # a crashed turn still beats
                    tc = globals().get("team_commit")
                    if tc is not None and w is not None and w.snap is not None:
                        tc(w, w.snap, team_task(dec))
                except Exception:
                    pass
            if pending:                                                           # boot: lazy parts (setup jobs)
                try:
                    if w is not None and w.stage == 2 and w.queue and w.queue[0] in INDEX_JOBS:
                        w.work_index()                                            # the camp index first (snapshot)
                    k = load_parts(pending, idle_load >= 2)
                    idle_load = 0 if k else idle_load + 1
                except Exception as e:
                    act_ += " l" + err_text(e)
            try:                                                                  # 7 FACTS (before background)
                if w is not None and w.snap is not None:
                    s = w.snap
                    p = nav.dest if nav.moved_round == rnd else s.pos
                    facts = (p,) + (w.facts(s, p) if s.alive else (0, "-", "-", "-"))
            except Exception as e:
                act_ += " f" + err_text(e)
            try:
                if w is not None and w.stage == 2:
                    jobs, bgf = w.work()                                          # 8 BACKGROUND
                    if dec is not None and dec.ticked:
                        j2, f2 = dec.work()
                        jobs, bgf = jobs + j2, bgf + f2
            except Exception as e:
                act_ += " w" + err_text(e)
            try:                                                                  # 7' TRACE
                if facts is not None:
                    s = w.snap
                    p, inc, on, gst, dead = facts
                    k = dec.key if dec is not None and dec.key is not None else "-"
                    fight = dec.fight if dec is not None and dec.fight is not None else "-"
                    hit = (dec.hit or "-") if dec is not None else "-"
                    full = rnd % FULL_EVERY == 0 or not q_done
                    ex = "".join(f" {n}={v}" for n, v in (("bag", s.bag), ("inc", inc), ("fight", fight),
                                                         ("on_spawn", on), ("gstate", gst), ("dead", dead),
                                                         ("hit", hit))
                                 if full or (v != 0 and v != "-"))
                    if not q_done:
                        ex += f" q={w.done()}/{w.total or '-'}"
                        q_done = w.total > 0 and w.done() == w.total
                    if jobs:
                        ex += f" +{jobs} bg={jobs}/{bgf}"
                    if full or sc > SNAP_WARN:
                        ex += f" snap={sc}"
                    trace("t", f"{p.x},{p.y} {FUEL.used()} {act_} tgt={k}{ex}")
                else:
                    p = cambc.me().position()
                    trace("t", f"{p.x},{p.y} {FUEL.used()} {act_} tgt=- q=- +0")
                for tag, text in EVENTS:
                    trace(tag, text)
                EVENTS.clear()
                while nav is not None and nav.legs:
                    k, d0, took, res = nav.legs.pop(0)
                    trace("leg", f"{k} d0={d0} took={took} {res}")
                if rnd >= LAST_ROUND - 1 and dec is not None:
                    dec.report()
            except Exception as e:
                trace("t", f"0,0 {FUEL.used()} {err_text(e)} tgt=- q=- +0")
            cambc.end_turn()

    play_main()
